wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105164473396661681)
,p_name=>'APEXAPP.TASK.DETAILS_PAGE_DEVELOPER_INFORMATION'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Diese Seite enth\00E4lt detaillierte Informationen zur Human Task, deren ID'),
unistr('an das Seitenelement <strong>Pnn_TASK_ID</strong> \00FCbergeben wurde. Sie dient als Vorlage, mit der Sie'),
unistr('die Aufgabendetailseite erstellen k\00F6nnen, auf der Benutzer'),
unistr('die Aufgabe ausf\00FChren. APEX hat diese Seite mit allen f\00FCr'),
unistr('Human Tasks verf\00FCgbaren Services f\00FCr Sie generiert. Dazu geh\00F6ren Services wie die Folgenden:</p>'),
'',
'<ul>',
'    <li>Aufgaben beanspruchen, freigeben und delegieren</li>',
unistr('    <li>F\00E4lligkeitsdatum, Ablauf und Verl\00E4ngerung von Aufgaben</li>'),
'    <li>Weitere Informationen vom Ersteller anfordern und angeben</li>',
'    <li>Aufgaben kommentieren</li>',
'    <li>Aufgabenhistorie</li>',
'    <li>Aufgabenfortschritt speichern und eine abgeschlossene Aufgabe weiterleiten</li>',
'</ul>',
'',
unistr('<p>Sie k\00F6nnen diese Region sowie alle Aufgabenserviceregionen oder -schaltfl\00E4chen l\00F6schen, die'),
unistr('f\00FCr Ihre Anwendung nicht erforderlich sind. F\00FCgen Sie dann Regionen hinzu, die'),
'die Aufgabe implementieren, die Benutzer in Ihrer',
unistr('Anwendung ausf\00FChren m\00FCssen. Dazu k\00F6nnen Sie Formulare, Berichte, Karten oder andere APEX-'),
unistr('Regionstypen auf dieser Seite hinzuf\00FCgen, genauso wie auf einer normalen Seite.</p>'),
'',
unistr('<p>Sie m\00FCssen sicherstellen, dass die Seitenverarbeitung Prozesse umfasst, die'),
unistr('Ihre Daten in der Datenbank aktualisieren. Diese m\00FCssen \00FCber die Schaltfl\00E4chen'),
unistr('<strong>Speichern</strong> und <strong>Abschlie\00DFen</strong> ausgef\00FChrt werden. Der Prozess'),
'<strong>Automatische Zeilenverarbeitung</strong> muss',
unistr('<strong>vor Ausf\00FChrung des Prozesses "Human Task - Verwalten"</strong> stattfinden.</p>')))
,p_version_scn=>2563916
);
