 p_id=>wwv_flow_imp.id(106770257544662181)
,p_name=>'CA.MASTER'
,p_message_language=>'de'
,p_message_text=>unistr('Master/Detail-Seite hinzuf\00FCgen')
,p_version_scn=>2564142
