wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105169293280661683)
,p_name=>'CA.PWA.DETAIL'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Progressive Web-Apps sind funktionsf\00E4hige, zuverl\00E4ssige und installierbare Webanwendungen. Eine progressive Web-App wirkt wie eine plattformspezifische Anwendung.</p>'),
'<p>Wenn Sie diese Option aktivieren, geschieht Folgendes:</p>',
'<ul>',
unistr('<li>Der neue Navigationsleisteneintrag "App installieren" wird hinzugef\00FCgt</li>'),
unistr('<li>Benutzer k\00F6nnen diese APEX-App auf Ger\00E4ten installieren</li>'),
'</ul>',
'<p><p/>',
unistr('<p>Wenn "Persistente Authentifizierung" f\00FCr diese Instanz aktiviert ist, wird auf der Anmeldeseite das Kontrollk\00E4stchen "Angaben speichern" angezeigt. Ist dieses Kontrollk\00E4stchen aktiviert, k\00F6nnen Endbenutzer bei ihren progressiven Webanwendungen ang')
||'emeldet bleiben.</p>',
'<p><p/>'))
,p_version_scn=>2563916
);
