,p_name=>'PE.PROPERTY.ACTION_CONDITION_JS_EXPRESSION_BOOLEAN.EXAMPLES'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>F\00FCr eine erfolgreiche R\00FCckgabe, wenn der Mitarbeiter in Abteilung 30 besch\00E4ftigt oder ein Manager ist:</dt>'),
'<dd><pre>',
'( apex.env.P2_DEPTNO === "30" || apex.env.P2_JOB === "MANAGER" )',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564026
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106046434882661962)
,p_name=>'PE.PROPERTY.ACTION_CONDITION_JS_EXPRESSION_BOOLEAN.PROMPT'
,p_message_language=>'de'
,p_message_text=>'JavaScript-Ausdruck'
,p_version_scn=>2564053
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105848200482661903)
,p_name=>'PE.PROPERTY.ACTION_CONDITION_JS_FUNC_BODY_BOOLEAN.EXAMPLES'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>F\00FCr eine erfolgreiche R\00FCckgabe, wenn der Mitarbeiter in Abteilung 30 besch\00E4ftigt ist:</dt>'),
'<dd><pre>',
'let deptno,',
'    rows;',
'',
'rows = apex.conn.execute( "select deptno from emp empno = :1", [ apex.env.P2_EMPNO ] ).rows;',
'for (let row of rows) {',
'  deptno = row.DEPTNO;',
'}',
'',
'return ( deptno === 30 );',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564026
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106046863257661962)
