wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105128957004661671)
,p_name=>'PE.PROPERTY.AI_SYSTEM_PROMPT.EXAMPLES'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Sie sind Marketingexperte. Sie erhalten eine Produktbeschreibung und Seed-W\00F6rter und sollen daraus Produktnamen generieren.</p>'),
unistr('<p>Sie sind professioneller \00DCbersetzer. Sie erhalten einen englischen Satz, den Sie ins Franz\00F6sische \00FCbersetzen sollen.</p>')))
,p_version_scn=>2563908
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105016401443661638)
,p_name=>'PE.PROPERTY.AI_SYSTEM_PROMPT.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie die anf\00E4nglichen Anweisungen oder den Kontext f\00FCr den KI-Service ein. Ein gut formulierter System-Prompt beeinflusst das Verhalten der KI und den Ton ihrer Antworten.'),
unistr('Um einen effektiven System-Prompt zu erstellen, geben Sie zun\00E4chst klar die Rolle oder das Fachgebiet f\00FCr die KI an. Geben Sie als N\00E4chstes die Aufgabe oder die Art der Antworten an, die Sie von der KI erwarten.</p>'),
unistr('<p>Hinweis: Wenn Sie sich nicht sicher sind, wie ein effektiver System-Prompt erstellt wird, lesen Sie die Dokumentation Ihres KI-Service. Sie k\00F6nnen auch bei einem generativen KI-System Hilfe zur Formulierung eines Prompts anfordern.'),
unistr('Beispiel f\00FCr eine entsprechende Aufforderung: <em>"Hilf mir, einen System-Prompt f\00FCr einen KI-Assistenten zu schreiben, der relevante Tags oder Schl\00FCsselw\00F6rter aus einem angegebenen Text extrahieren soll."</em></p>')))
,p_version_scn=>2563877
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105016381431661638)
,p_name=>'PE.PROPERTY.AI_SYSTEM_PROMPT.PROMPT'
,p_message_language=>'de'
,p_message_text=>'System-Prompt'
,p_version_scn=>2563877
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105055472749661649)
,p_name=>'PE.PROPERTY.AI_TEMPERATURE.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie an, wie kreativ und zuf\00E4llig die Antworten sein sollen. Eine niedrigere Temperatur bewirkt eine eher fokussierte, deterministische und konventionelle Ausgabe mit g\00E4ngigen oder berechenbaren Antworten. Eine h\00F6here Temperatur erh\00F6ht die Kr')
||unistr('eativit\00E4t des Modells, sodass es eher vielf\00E4ltige und unkonventionelle Antworten ausgibt. Passen Sie die Temperatur dem gew\00FCnschten Verh\00E4ltnis von Pr\00E4zision und Kreativit\00E4t in der Antwort an.</p>'),
unistr('<p>Hinweis: Die Temperatur kann vom KI-Service abh\00E4ngen. Es wird empfohlen, bei der Wahl des geeigneten Wertes die Temperaturwerte des KI-Service zu ber\00FCcksichtigen.</p>')))
,p_version_scn=>2563888
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105055365679661649)
,p_name=>'PE.PROPERTY.AI_TEMPERATURE.PROMPT'
,p_message_language=>'de'
,p_message_text=>'Temperatur '
,p_version_scn=>2563888
);
