,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Geben Sie einen JavaScript-Funktionsbody mit booleschem R\00FCckgabewert ein, der bei Ausf\00FChrung der Automatisierung ausgef\00FChrt wird.'),
unistr('Wenn der Funktionsbody <strong>true</strong> zur\00FCckgibt, werden die Aktionen ausgef\00FChrt.')))
,p_version_scn=>2564053
);
