wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105443740253661764)
,p_name=>'PE.PROPERTY.CONFIRM_ENABLED.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Sch\00FCtzen Sie das Verhalten der Schaltfl\00E4che mit einem Best\00E4tigungs-Prompt. Dieser zeigt ein Best\00E4tigungsdialogfeld nach dem Klicken auf die Schaltfl\00E4che an. Dort muss der Benutzer den Vorgang best\00E4tigen, bevor die Schaltfl\00E4chenaktion ausgef\00FChrt wi')
||'rd.</p>',
unistr('<p>Mit dieser Funktion k\00F6nnen Sie sicherstellen, dass Benutzer nicht versehentlich wichtige Aktionen ausf\00FChren, wie das L\00F6schen eines Datensatzes.</p>'),
unistr('<p>Hinweis: Die Best\00E4tigungsschaltfl\00E4che im Dialogfeld \00FCbernimmt das Label vom Label der Hauptschaltfl\00E4che.</p>')))
,p_version_scn=>2563969
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105443625221661764)
,p_name=>'PE.PROPERTY.CONFIRM_ENABLED.PROMPT'
,p_message_language=>'de'
,p_message_text=>unistr('Best\00E4tigung erforderlich')
,p_version_scn=>2563969
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(104997233580661632)
,p_name=>'PE.PROPERTY.CONFIRM_MESSAGE.COMPONENT_PROPERTY.BUTTON.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Ber\00FCcksichtigen Sie beim Entwerfen von Dialogfeldern oder Prompts f\00FCr die Meldungsbest\00E4tigung unbedingt Barrierefreiheitsaspekte, damit alle Benutzer die Best\00E4tigungsmeldung leicht verstehen und damit interagieren k\00F6nnen.</p>'),
'<strong>Best Practices:</strong>',
'<ol>',
'<li><strong>Klarer und informativer Inhalt:</strong>',
unistr('Stellen Sie sicher, dass die Best\00E4tigungsmeldung klare und pr\00E4zise Informationen zur jeweiligen Aktion enth\00E4lt. Verwenden Sie einfache Formulierungen, die f\00FCr alle Benutzer leicht verst\00E4ndlich sind.</li>'),
'<li><strong>Barrierefreie Formatierung:</strong>',
unistr('Formatieren Sie die Best\00E4tigungsmeldung so, dass sie f\00FCr Benutzer verschiedener assistiver Technologien, wie Bildschirmsprachausgaben, barrierefrei ist. Verwenden Sie semantische HTML-Elemente, und geben Sie alternativen Text f\00FCr Nicht-Textelemente w')
||unistr('ie Schaltfl\00E4chen an.</li>'),
'<li><strong>Konsistentes Design:</strong>',
unistr('Bewahren Sie die Konsistenz im Design und in der Platzierung von Dialogfeldern zur Meldungsbest\00E4tigung in Ihrer Anwendung oder Website. Wenn das Design konsistent ist, k\00F6nnen Benutzer die Position der Best\00E4tigungsmeldung vorhersagen und sich besser o')
||'rientieren.</li>',
'<li><strong>Benutzerkontrolle:</strong>',
unistr('Bieten Sie Benutzern die Option, ihre Aktion vor der Best\00E4tigung zu pr\00FCfen, besonders bei kritischen oder irreversiblen Aktionen. So k\00F6nnen Benutzer fundierte Entscheidungen treffen, und die Wahrscheinlichkeit unbeabsichtigter Aktionen wird reduziert')
||'.</li>',
'</ol>',
unistr('<p>Indem Sie diese Barrierefreiheitsaspekte ber\00FCcksichtigen, stellen Sie sicher, dass Dialogfelder f\00FCr die Meldungsbest\00E4tigung f\00FCr alle Benutzer nutzbar sind, unabh\00E4ngig von ihren F\00E4higkeiten oder der Nutzung assistiver Technologien.</p>')))
,p_version_scn=>2563857
);
