'<ul>',
unistr('<li><strong>Zeile hinzuf\00FCgen</strong> wird von diesen Anforderungswerten ausgel\00F6st: INSERT, CREATE, CREATE_AGAIN, CREATEAGAIN</li>'),
unistr('<li><strong>Zeile aktualisieren</strong> wird von diesen Anforderungswerten ausgel\00F6st: SAVE, APPLY CHANGES, UPDATE, UPDATE ROW, CHANGE, APPLY, APPLY%CHANGES%, GET_NEXT%, GET_PREV%</li>'),
unistr('<li><strong>Zeile l\00F6schen</strong> wird von diesen Anforderungswerten ausgel\00F6st: DELETE, REMOVE, DELETE ROW, DROP</li>'),
'</ul>'))
,p_version_scn=>2563995
);
