wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105591216366661807)
,p_name=>'PE.PROPERTY.HELP_TEXT.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Mit diesem Attribut k\00F6nnen Sie den Hilfetext f\00FCr die aktuelle Seite eingeben. Die Hilfe auf Seitenebene unterst\00FCtzt Shortcuts mit folgender Syntax:</p>'),
'<pre>"SHORTCUT_NAME"</pre>',
unistr('<p>Hilfetext f\00FCr die Seite wird nicht standardm\00E4\00DFig angezeigt. Sie k\00F6nnen jedoch jederzeit ein Hilfesystem entwickeln, das Hilfetext ausgibt.</p>')))
,p_version_scn=>2563990
);
wwv_flow_imp_shared.create_message(
