wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105003735277661634)
,p_name=>'PE.PROPERTY.ICON_DESCRIPTION.COMPONENT_PROPERTY.CARD.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Die Symbolbeschreibung stellt ein wesentliches Feature der Barrierefreiheit dar. Sie bietet kontextbezogene Informationen zu einem Symbol, wenn Benutzer den Fokus darauf legen oder mit der Maus darauf zeigen. Dieses Feature erleichtert das Benutze'
||unistr('rverst\00E4ndnis und die Interaktion mit der Oberfl\00E4che.</p>'),
'<strong>Best Practices:</strong>',
'<ol>',
unistr('<li><strong>Klar und pr\00E4zise:</strong> Symbolbeschreibungen m\00FCssen klar und pr\00E4zise sein, um die Funktion oder den Zweck des Symbols mit einem kurzen, aber informativen Text zu erl\00E4utern.</li>'),
unistr('<li><strong>Beschreibende Formulierung:</strong> Verwenden Sie eine beschreibende Formulierung, die die Bedeutung oder Aktion des Symbols korrekt vermittelt. Vermeiden Sie mehrdeutige oder vage Beschreibungen, die Benutzer verwirren k\00F6nnten.</li>'),
'<li><strong>Notwendigkeit von alternativem Text bestimmen:</strong>',
unistr('Bewerten Sie, ob es das Seitenverst\00E4ndnis behindern w\00FCrde, wenn das Symbol nicht vorhanden w\00E4re.'),
unistr('Wenn die Seite ohne das Symbol weniger Sinn ergibt, f\00FCgen Sie alternativen Text hinzu.</li>'),
'</ol>'))
,p_version_scn=>2563870
);
