,p_name=>'PE.PROPERTY.ICON_VIEW_CUSTOM.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie die benutzerdefinierte Spalten-HTML f\00FCr die Symbolansicht ein.</p>'),
unistr('<p>Die folgenden Ersetzungszeichenfolgen sind verf\00FCgbar:'),
'<ul>',
unistr('<li><code>&&lt;COLUMN_NAME&gt;.</code>: Ersetzungszeichenfolgen f\00FCr Spaltennamen.</li>'),
unistr('<li><code>&&lt;COLUMN_NAME&gt;_LABEL.</code>: Ersetzungszeichenfolgen f\00FCr Spaltenlabels.</li>'),
unistr('<li><code>&APEX$ROW_ID.</code>: Die Datensatz-ID f\00FCr die Zeile.</li>'),
'<li><code>&APEX$ROW_INDEX.</code>: Die Folgenummer der Datensatzanzeige.</li>',
'<li><code>&APEX$ROW_URL.</code>: Die Referenz zum angegebenen Linkziel.</li>',
'<li><code>&APEX$ROW_STATE_CLASSES.</code>: Der Datensatzstatus, z.B. <code>is-inserted</code> oder <code>is-deleted</code>.</li>',
'</ul>',
'</p>'))
,p_version_scn=>2564055
);
