wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(104998729263661633)
,p_name=>'PE.PROPERTY.ICON_VIEW_HTML_ALT_TEXT.COMPONENT_PROPERTY.IR_ATTRIBUTES.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Alternativer Text beschreibt die von Symbolen vermittelten Informationen f\00FCr Benutzer assistiver Technologien und sorgt so f\00FCr eine barrierefreie Website.<p>'),
'<strong>Best Practices:</strong>',
'<ol>',
'<li><strong>Notwendigkeit von alternativem Text bestimmen:</strong>',
unistr('Bewerten Sie, ob es das Seitenverst\00E4ndnis behindern w\00FCrde, wenn das Symbol nicht vorhanden w\00E4re.'),
unistr('Wenn die Seite ohne das Symbol weniger Sinn ergibt, f\00FCgen Sie alternativen Text hinzu.</li>'),
unistr('<li><strong>\00DCberlegungen zu Text:</strong>'),
unistr('Pr\00FCfen Sie, ob angrenzender Text vorhanden und f\00FCr den Zweck des Symbols relevant ist.</li>'),
'',
'<li><strong>Empfehlungen:</strong>',
'<ul>',
unistr('<li>Das Hinzuf\00FCgen von Text zu Symbolen vergr\00F6\00DFert den anklickbaren/ber\00FChrbaren Bereich f\00FCr Links oder Schaltfl\00E4chen.</li>'),
unistr('<li>F\00FCgen Sie alternativen Text zu alleinstehenden Symbolen ohne sichtbaren angrenzenden Text hinzu, um die Barrierefreiheit f\00FCr alle Benutzer sicherzustellen.</li>'),
unistr('<li>Verwenden Sie konsistente, klare und verst\00E4ndliche Symbole</li>'),
'</ul>',
'</li>',
'</ol>'))
,p_version_scn=>2563859
);
