,p_name=>'PE.PROPERTY.INIT_JAVASCRIPT_FUNCTION.COMPONENT_PROPERTY.CARD.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie eine JavaScript-Funktion ein, die ein Optionsobjekt \00E4ndert und zur\00FCckgibt. Das erm\00F6glicht eine erweiterte Anpassung der Region bei der Initialisierung. Die verf\00FCgbaren Optionen finden Sie in der JavaScript-API-Dokumentation zum <code>tab')
||'leModelView</code>-Widget.</p>',
'<p>',
'Weitere von der Kartenregion definierte Optionen:',
'</p>',
'<ul>',
'<li>',
unistr('<strong>modelOptions</strong> Optionsobjekt, das an <code>apex.model.create</code> \00FCbergeben wird.</li>'),
'</ul>'))
,p_version_scn=>2563957
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105357437701661739)
,p_name=>'PE.PROPERTY.INIT_JAVASCRIPT_FUNCTION.COMPONENT_PROPERTY.IG_ATTRIBUTES.EXAMPLES'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'function( options ) {',
'    options.toolbar = false;',
'    return options;',
'}',
'</pre>'))
,p_version_scn=>2563957
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105357519961661739)
,p_name=>'PE.PROPERTY.INIT_JAVASCRIPT_FUNCTION.COMPONENT_PROPERTY.IG_ATTRIBUTES.HELP'
,p_message_language=>'de'
,p_message_text=>unistr('Geben Sie eine JavaScript-Funktion ein, die ein Konfigurationsobjekt f\00FCr das interaktive Grid verwendet, das Objekt \00E4ndert und zur\00FCckgibt. Dies erm\00F6glicht eine erweiterte Anpassung der Darstellung, der Features und des Verhaltens des interaktiven Gri')
||unistr('ds, einschlie\00DFlich Symbolleiste, Men\00FCs und Aktionen.')
,p_version_scn=>2563957
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105357874717661739)
,p_name=>'PE.PROPERTY.INIT_JAVASCRIPT_FUNCTION.COMPONENT_PROPERTY.JET_CHART.EXAMPLES'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'function( options ){',
'    // Richtet eine Callback-Funktion ein, die aufgerufen wird, wenn Daten abgerufen werden. Mit ihr kann die Reihe bearbeitet werden',
'    options.dataFilter = function( data ) {',
'        data.series[ 0 ].color = "#00FF00";',
'        return data;',
'    };',
'    // Legt Optionen zur Diagramminitialisierung fest',
'    options.type = "line";',
'    return options;',
'}</pre>'))
,p_version_scn=>2563957
);
