,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Abfrage, die NUMBER-Spalten zur Bestimmung der anf\00E4nglichen Kartenposition und des Zoomfaktors zur\00FCckgibt:</p>'),
'<pre>',
'select -133.5 longitude,',
'         35.2 latitude,',
'            3 zoom',
'  from sys.dual',
'</pre>',
unistr('<p>Abfrage, die eine SDO_GEOMETRY-Spalte zur Bestimmung der anf\00E4nglichen Kartenposition und eine NUMBER-Spalte f\00FCr den Zoomfaktor zur\00FCckgibt.</p>'),
'<pre>',
'select sdo_geometry( 2001,                                 -- 2 dimensional point',
'                     4326,                                 -- longitude/latitude (WGS84)',
'                     sdo_point_type( -133.5, 35.2, null ), -- concrete coordinates',
'                     null,                                 -- not used for points',
'                     null                                  -- not used for points',
'       )                   as geometry,',
'       3                   as zoom',
'  from sys.dual',
'</pre>'))
,p_version_scn=>2564099
);
