wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105002909864661634)
,p_name=>'PE.PROPERTY.JET_REFERENCE_LINE_COLORS.COMPONENT_PROPERTY.JET_CHART_SERIES.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Die Verbesserung der Barrierefreiheit von Diagrammen durch bewusst gew\00E4hlte Farben und Einhaltung von WCAG-Standards ist f\00FCr Inklusivit\00E4t in der Datenvisualisierung unerl\00E4sslich.</p>'),
'<strong>Best Practices:</strong>',
'<ol>',
unistr('<li><strong>Kr\00E4ftige und hervorstechende Farben verwenden:</strong> Verwenden Sie kr\00E4ftige und hervorstechende Farben, um sicherzustellen, dass Text und grafische Elemente in Ihren Diagrammen leicht zu erkennen sind. So verbessern Sie die Lesbarkeit ')
||unistr('und das Verst\00E4ndnis f\00FCr alle Benutzer, einschlie\00DFlich derer mit eingeschr\00E4nktem Sehverm\00F6gen.</li>'),
unistr('<li><strong>Farbkontrastverh\00E4ltnis pr\00FCfen:</strong> Nutzen Sie Kontrastpr\00FCfungstools, um das Farbkontrastverh\00E4ltnis zwischen Vordergrund- und Hintergrundfarben zu bewerten. Verwenden Sie nach M\00F6glichkeit mindestens das Verh\00E4ltnis 4,5:1, um Lesbarkeit')
||unistr(' f\00FCr Personen mit unterschiedlichen Sehbehinderungsgraden sicherzustellen.</li>'),
'</ol>'))
,p_version_scn=>2563868
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105365520150661741)
,p_name=>'PE.PROPERTY.JET_REFERENCE_LINE_COLORS.EXAMPLES'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl>',
'<dt>Eine durch Komma getrennte Liste mit Farben:</dt>',
'<dd><pre>',
'<strong>red,yellow,blue</strong>',
'</pre></dd>',
unistr('<dt>Eine durch Komma getrennte Liste mit Seiten- oder Anwendungselementen, die Farben zur\00FCckgeben, mit:</dt>'),
'<dd><pre>',
'<code>&amp;ITEM.</code>-Syntax. Beispiel: <strong><code>&amp;ITEM_1.</code>,<code>&amp;ITEM_2.</code>,<code>&amp;ITEM_3.</code></strong>',
'</pre></dd>',
unistr('<dt>Eine durch Komma getrennte Liste mit Spalten, die Farben zur\00FCckgeben, mit:</dt>'),
'<dd><pre>',
'<code>&amp;COLUMN_NAME.</code>-Syntax. Beispiel: <strong><code>&amp;COLUMN_NAME_1.</code>,<code>&amp;COLUMN_NAME_2.</code>,<code>&amp;COLUMN_NAME_3.</code></strong>',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2563959
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105365433301661741)
,p_name=>'PE.PROPERTY.JET_REFERENCE_LINE_COLORS.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Geben Sie die Farben ein, mit denen die anzuzeigenden Referenzlinien in einem Statusgaugediagramm identifiziert werden.',
'Geben Sie mehrere Referenzlinien in einer durch Komma getrennten Liste ein.'))
,p_version_scn=>2563959
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105365193969661741)
,p_name=>'PE.PROPERTY.JET_REFERENCE_LINE_COLORS.PROMPT'
,p_message_language=>'de'
,p_message_text=>'Farben'
,p_version_scn=>2563959
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105365302524661741)
,p_name=>'PE.PROPERTY.JET_REFERENCE_LINE_VALUES.EXAMPLES'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl>',
'<dt>Eine durch Komma getrennte Liste mit statischen numerischen Werten:</dt>',
'<dd><pre>',
'<strong>5,10,15</strong>',
'</pre></dd>',
unistr('<dt>Eine durch Komma getrennte Liste mit Seiten- oder Anwendungselementen, die numerische Werte zur\00FCckgeben, mit:</dt>'),
'<dd><pre>',
'<code>&amp;ITEM.</code>-Syntax. Beispiel: <strong><code>&amp;ITEM_1.</code>,<code>&amp;ITEM_2.</code>,<code>&amp;ITEM_3.</code></strong>',
'</pre></dd>',
unistr('<dt>Eine durch Komma getrennte Liste mit Spalten, die numerische Werte zur\00FCckgeben, mit:</dt>'),
'<dd><pre>',
'<code>&amp;COLUMN_NAME.</code>-Syntax. Beispiel: <strong><code>&amp;COLUMN_NAME_1.</code>,<code>&amp;COLUMN_NAME_2.</code>,<code>&amp;COLUMN_NAME_3.</code></strong>',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2563959
);
