);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105159058365661680)
,p_name=>'PE.PROPERTY.LANDMARK_TYPE.LOV.CONTENTINFO.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>Mit einer <code>contentinfo</code>-Landmark k\00F6nnen Sie unten auf jeder Seite einer Anwendung (in der Regel als "Footer" bezeichnet)'),
'allgemeine Informationen angeben.</p>',
unistr('<p>Seiten haben in der Regel nur eine <code>contentinfo</code>-Landmark, und f\00FCr gew\00F6hnlich beziehen APEX-Seiten diese <code>contentinfo</code>-'),
'Landmark aus dem Seitentemplate. Daher kommt es wahrscheinlich selten vor, dass Seitenregionen in APEX als <code>contentinfo</code>-Regionen definiert werden.</p>',
''))
,p_version_scn=>2563915
);
