,p_name=>'PE.PROPERTY.MAP_FEATURE_INFOWINDOW_HTML_EXPR.EXAMPLES'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
unistr('  <dt>Hintergrund- und Textfarben \00E4ndern</dt>'),
'    <dd><pre>&lt;span style="background-color:yellow; color:red;">&EMPLOYEE_STATUS.&lt;/span></pre></dd>',
unistr('  <dt>\00DCberschrift 2 verwenden</dt>'),
'    <dd><pre>&lt;h2>&EMPLOYEE_NAME.&lt;/h2></pre></dd>',
'  <dt>Eine dynamische Klasse aus der SQL-Abfrage verwenden</dt>',
'    <dd><pre>&lt;span class="&COLUMN_CLASS.">&EMPLOYEE_STATUS.&lt;/span></pre><br>',
unistr('    Die Ersetzungen <code>&COLUMN_CLASS.</code> und <code>&EMPLOYEE_STATUS.</code> in diesem Beispiel sind Spalten, die in der Berichts-SQL-Abfrage ausgew\00E4hlt werden.</dd>'),
'  <dt>Beim Mouseover ein Bild und eine QuickInfo anzeigen</dt>',
'    <dd><pre>&lt;img src="&IMAGE_NAME." title="&EMPLOYEE_NAME."&gt;</pre></dd>',
'</dl>'))
,p_version_scn=>2564103
);
