wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105003432576661634)
,p_name=>'PE.PROPERTY.MAP_FEATURE_POINT_FILL_COLOR.COMPONENT_PROPERTY.MAP_LAYER.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Die Verbesserung der Barrierefreiheit von Karten durch bewusst gew\00E4hlte Farben und Einhaltung von WCAG-Standards ist f\00FCr Inklusivit\00E4t in der Datenvisualisierung unerl\00E4sslich.</p>'),
'<strong>Best Practices:</strong>',
'<ol>',
unistr('<li><strong>Kr\00E4ftige und hervorstechende Farben verwenden:</strong> Verwenden Sie kr\00E4ftige und hervorstechende Farben, um sicherzustellen, dass Text und grafische Elemente in Ihrer Karte leicht zu erkennen sind. So verbessern Sie die Lesbarkeit und d')
||unistr('as Verst\00E4ndnis f\00FCr alle Benutzer, einschlie\00DFlich derer mit eingeschr\00E4nktem Sehverm\00F6gen.</li>'),
unistr('<li><strong>Farbkontrastverh\00E4ltnis pr\00FCfen:</strong> Nutzen Sie Kontrastpr\00FCfungstools, um das Farbkontrastverh\00E4ltnis zwischen Vordergrund- und Hintergrundfarben zu bewerten. Verwenden Sie nach M\00F6glichkeit mindestens das Verh\00E4ltnis 4,5:1, um Lesbarkeit')
||unistr(' f\00FCr Personen mit unterschiedlichen Sehbehinderungsgraden sicherzustellen.</li>'),
'</ol>'))
,p_version_scn=>2563868
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106492140575662095)
,p_name=>'PE.PROPERTY.MAP_FEATURE_POINT_FILL_COLOR.EXAMPLES'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Beispiele f\00FCr die HTML-Hauptfarbcodes umfassen -'),
'<ul>',
'  <li><strong><span style="background-color: lightgray; color: black;">&nbsp;&nbsp;Schwarz&nbsp;&nbsp;</span></strong> <code>#000000 RGB(0,0,0)</code></li>',
'  <li><strong><span style="background-color: lightgray; color: red;">&nbsp;&nbsp;Rot&nbsp;&nbsp;</span></strong> <code>#FF0000 RGB(255,0,0)</code></li>',
'  <li><strong><span style="background-color: lightgray; color: yellow;">&nbsp;&nbsp;Gelb&nbsp;&nbsp;</span></strong> <code>#FFFF00 RGB(255,255,0)</code></li>',
'  <li><strong><span style="background-color: lightgray; color: lime;">&nbsp;&nbsp;Limone&nbsp;&nbsp;</span></strong> <code>#00FF00 RGB(0,255,0)</code></li>',
unistr('  <li><strong><span style="background-color: lightgray; color: green;">&nbsp;&nbsp;Gr\00FCn&nbsp;&nbsp;</span></strong> <code>#008000 RGB(0,128,0)</code></li>'),
'  <li><strong><span style="background-color: lightgray; color: aqua;">&nbsp;&nbsp;Aquamarin&nbsp;&nbsp;</span></strong> <code>#00FFFF RGB(0,255,255)</code></li>',
'  <li><strong><span style="background-color: lightgray; color: blue;">&nbsp;&nbsp;Blau&nbsp;&nbsp;</span></strong> <code>#0000FF RGB(0,255,255)</code></li>',
'  <li><strong><span style="background-color: lightgray; color: navy;">&nbsp;&nbsp;Marineblau&nbsp;&nbsp;</span></strong> <code>#000080 RGB(0,0,128)</code></li>',
unistr('  <li><strong><span style="background-color: lightgray; color: white;">&nbsp;&nbsp;Wei\00DF&nbsp;&nbsp;</span></strong> <code>#FFFFFF RGB(255,255,255)</code></li>'),
'</ul>'))
,p_version_scn=>2564106
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106492049121662095)
,p_name=>'PE.PROPERTY.MAP_FEATURE_POINT_FILL_COLOR.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Geben Sie die F\00FCllfarbe des Markers an.'),
'<p>Die Farbe wird mit der Hexadezimalschreibweise (Hex), mit RGB-Farbcodes oder mit HTML-Farbnamen angegeben. Die Hex-Schreibweise wird als #xxyyzz (ein # gefolgt von einem sechsstelligen Hexadezimalcode) definiert, wobei xx, yy und zz die beiden Hex'
||unistr('adezimalzeichenwerte f\00FCr rot, gr\00FCn bzw. blau darstellen.'),
unistr('RGB-Codes werden als RGB(xxx,xxx,xxx) definiert, wobei xxx eine Zahl zwischen 0 und 255 ist, die jeweils den einzelnen 8-Bit-Bytewert f\00FCr rot, gr\00FCn bzw. blau darstellt.</p>'),
unistr('<p>Im Internet finden Sie unter "HTML-Farbcodes" den entsprechenden Hexadezimalcode oder RGB-Code f\00FCr die Farbe, die Sie verwenden m\00F6chten.</p>')))
,p_version_scn=>2564106
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106491926420662095)
,p_name=>'PE.PROPERTY.MAP_FEATURE_POINT_FILL_COLOR.PROMPT'
,p_message_language=>'de'
,p_message_text=>unistr('F\00FCllfarbe')
,p_version_scn=>2564106
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106491811739662095)
,p_name=>'PE.PROPERTY.MAP_FEATURE_POINT_FILL_OPACITY.HELP'
