wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(104995384443661632)
,p_name=>'PE.PROPERTY.PAGE_WARN_ON_UNSAVED_CHANGES.COMPONENT_PROPERTY.PAGE.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Beim Entwurf von Webseiten m\00FCssen Sie die Benutzererfahrung priorisieren, indem Sie Features zur Verhinderung von Datenverlust implementieren. Wenn Sie die Funktionalit\00E4t zum Warnen bei nicht gespeicherten Seiten\00E4nderungen aktivieren, werden Benut')
||unistr('zer benachrichtigt, bevor sie eine Seite mit nicht gespeicherten \00C4nderungen verlassen.'),
unistr('Dieses Feature verbessert nicht nur die Benutzerfreundlichkeit, sondern sorgt auch f\00FCr Datenintegrit\00E4t und Benutzerzufriedenheit.</p>')))
,p_version_scn=>2563854
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106514348630662102)
,p_name=>'PE.PROPERTY.PAGE_WARN_ON_UNSAVED_CHANGES.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie an, ob der Benutzer gewarnt wird, wenn er versucht, aus der Seite zu navigieren, w\00E4hrend die Seite nicht gespeicherte \00C4nderungen enth\00E4lt.'),
unistr('        Seitenelemente und Schaltfl\00E4chen bieten au\00DFerdem eine genauere Kontrolle \00FCber die Ausf\00FChrung dieser Pr\00FCfung und deren Inhalt.'),
unistr('        Bei Schaltfl\00E4chen k\00F6nnen Sie angeben, ob die Pr\00FCfung beim Klicken auf die Schaltfl\00E4che ausgef\00FChrt wird.'),
unistr('        Bei Seitenelementen k\00F6nnen Sie angeben, ob \00C4nderungen am Element bei der Pr\00FCfung einbezogen oder ignoriert werden (hierzu wird auf das Attribut <em>Warnung bei nicht gespeicherten \00C4nderungen</em> f\00FCr beide F\00E4lle verwiesen).</p>'),
unistr('        <p>Hinweis: Diese Einstellung gilt nicht f\00FCr Endbenutzer, die ein Modaldialogfeld schlie\00DFen.</p>')))
,p_version_scn=>2564108
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106514229349662102)
,p_name=>'PE.PROPERTY.PAGE_WARN_ON_UNSAVED_CHANGES.PROMPT'
,p_message_language=>'de'
,p_message_text=>unistr('Warnung bei nicht gespeicherten \00C4nderungen')
,p_version_scn=>2564108
);
