unistr('<dl><dt>F\00FCr einen R\00FCckgabewert "Erfolgreich", wenn eine oder mehrere Zeilen vorhanden sind, und wenn gepr\00FCft wird, ob der Mitarbeiter in Abteilung 30 besch\00E4ftigt ist:</dt>'),
'<dd><pre>',
'select 1',
'  from emp',
' wobei empno  = :P2_EMPNO',
'   und deptno = 30',
'</pre></dd>',
unistr('<dt>F\00FCr einen R\00FCckgabewert "Erfolgreich", wenn keine Zeilen vorhanden sind, und wenn gepr\00FCft wird, ob der Mitarbeiter in Abteilung 40 besch\00E4ftigt ist:</dt>'),
'<dd><pre>',
'select 1',
'  from emp',
' wobei empno  = :P2_EMPNO',
'   und deptno = 40',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564026
);
