,p_name=>'PE.PROPERTY.READ_ONLY_CONDITION_TYPE.COMPONENT_PROPERTY.PAGE_ITEM.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>W\00E4hlen Sie einen Bedingungstyp, der erf\00FCllt werden muss, damit diese Komponente als schreibgesch\00FCtzte Komponente wiedergegeben wird. Wenn Sie keine Bedingung ausw\00E4hlen, wird das Element normal wiedergegeben. '),
unistr('Ein schreibgesch\00FCtztes Element wird mit denselben Einstellungen wie ein Element "Nur anzeigen" wiedergegeben.</p>'),
'<p>Hinweis: Setzen Sie den Bedingungstyp auf <strong>Nie</strong>, wenn das Element immer als Feld angezeigt werden soll, in das ein Wert eingegeben werden kann. ',
unistr('Dadurch wird jede Schreibschutz-Bedingungseinstellung auf Regions- oder Seitenebene \00FCberschrieben.</p>')))
,p_version_scn=>2563839
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105791873631661867)
,p_name=>'PE.PROPERTY.READ_ONLY_CONDITION_TYPE.COMPONENT_PROPERTY.REGION.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>W\00E4hlen Sie einen Bedingungstyp aus der Liste aus, der erf\00FCllt werden muss, damit Seitenelemente in dieser Region schreibgesch\00FCtzt wiedergegeben werden. '),
unistr('Wenn Sie keine Bedingung ausw\00E4hlen, werden die Seitenelemente normal wiedergegeben.</p>'),
unistr('<p>Hinweis: Wenn ein Seitenelement dieser Region (z.B. ein Suchfeld) unabh\00E4ngig von der Auswertung dieser Bedingung immer als bearbeitbares Seitenelement wiedergegeben werden soll, m\00FCssen Sie die Schreibschutzbedingung dieses Seitenelements auf "Nie"')
||unistr(' setzen, um die Regionseinstellung zu \00FCberschreiben.</p>')))
,p_version_scn=>2564012
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105599243204661810)
,p_name=>'PE.PROPERTY.READ_ONLY_CONDITION_TYPE.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>W\00E4hlen Sie einen Bedingungstyp aus, der erf\00FCllt werden muss, damit Seitenelemente auf dieser Seite schreibgesch\00FCtzt wiedergegeben werden. Wenn Sie keine Bedingung ausw\00E4hlen, werden die Seitenelemente normal wiedergegeben. '),
unistr('Die Schreibschutzbedingung wird ausgewertet, nachdem die Prozesse mit dem Verarbeitungspunkt <em>Vor Header</em> ausgef\00FChrt wurden.</p>'),
unistr('<p>Hinweis: Wenn einige Seitenelemente (z.B. ein Suchfeld) oder alle Seitenelemente einer speziellen Region unabh\00E4ngig von der Auswertung dieser Bedingung immer als bearbeitbare Seitenelemente wiedergegeben werden sollen, m\00FCssen Sie die Schreibschutz')
||unistr('bedingung dieser Regionen/Seitenelemente auf <strong>Nie</strong> setzen, um die \00FCbergeordnete Einstellung zu \00FCberschreiben.</p>')))
,p_version_scn=>2563991
);
