wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105790728962661866)
,p_name=>'PE.PROPERTY.REGION_DISPLAY_SELECTOR.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Geben Sie <strong>Ein</strong> an, wenn diese Region in den Regionsanzeigeselektor aufgenommen werden soll.',
unistr('Dieses Attribut wird nur verwendet, wenn der Regionstyp <em>Selektor f\00FCr Regionsanzeige</em> definiert und auf der Seite sichtbar ist.</p>'),
unistr('<p>Wenn ein Benutzer auf einen Regionsnamen klickt, der im Regionsanzeigeselektor enthalten ist, wird nur die ausgew\00E4hlte Region angezeigt, und alle anderen Regionen sind ausgeblendet.'),
unistr('Der erste Eintrag im Regionsanzeigeselektor ist <em>Alle anzeigen</em>. Damit k\00F6nnen Benutzer alle verf\00FCgbaren Regionen und nicht nur die vorher ausgew\00E4hlte Region anzeigen.</p>'),
'<p>Wenn eine Region aufgrund der Regionsbedingungen nicht angezeigt werden kann, ist sie nicht in der Liste der Regionen innerhalb des Regionsanzeigeselektors enthalten.</p>'))
,p_version_scn=>2564012
);
