wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(104998006159661632)
,p_name=>'PE.PROPERTY.REGION_IMAGE_ALT_TEXT.COMPONENT_PROPERTY.REGION.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Alternativer Text dient als wesentliches Element zum Verbessern der Barrierefreiheit f\00FCr Benutzer mit eingeschr\00E4nkter Sehf\00E4higkeit. Er enth\00E4lt eine Beschreibung der Bilder in Dokumenten oder auf Webseiten und erl\00E4utert ihre Bedeutung im Zusammenha')
||'ng mit dem Inhalt.</p>',
'<strong>Best Practices:</strong>',
'<ol>',
'<li>Relevante Beschreibung:',
'<ul>',
'<li>Alternativer Text muss die Bedeutung des Bildes im Zusammenhang mit dem umgebenden Inhalt kurz und knapp vermitteln.</li>',
'<li>Beschreiben Sie den Zweck des Bildes und nicht nur, was es zeigt.</li>',
unistr('<li>Verfassen Sie klaren, pr\00E4zisen und aussagekr\00E4ftigen alternativen Text.</li>'),
'</ul>',
'</li>',
'<strong>Beispiel:</strong>',
unistr('<p>"L\00E4chelnde Teammitglieder feiern mit High-Fives den erfolgreichen Abschluss eines schwierigen Projekts."</p>'),
unistr('In diesem Beispiel betont der alternative Text den Grund f\00FCr die Situation auf dem Bild, n\00E4mlich den erfolgreichen Abschluss eines schwierigen Projekts und die Freude der Teammitglieder. Diese Beschreibung bietet Kontext f\00FCr das Bild und erl\00E4utert se')
||unistr('ine Bedeutung den Benutzern, die es nicht direkt sehen k\00F6nnen.'),
'<li>Informative Bilder:',
unistr('Identifizieren Sie Bilder, die zum Verst\00E4ndnis der Webseite beitragen oder ihren Kontext verdeutlichen.'),
unistr('Wenn ein Bild f\00FCr die Bedeutung der Seite entscheidend ist, ben\00F6tigt es einen alternativen Text.</li>'),
'<li>Redundanz vermeiden:',
'Lassen Sie Phrasen wie "Bild von " weg, da die Bildschirmsprachausgabe ein Bild automatisch beim Vorlesen als Bild identifiziert.</li>',
'</ol>'))
,p_version_scn=>2563857
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106032013315661957)
,p_name=>'PE.PROPERTY.REGION_IMAGE_ALT_TEXT.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie beschreibenden Text f\00FCr das Bild ein, das im HTML Alt-Attribut f\00FCr das Bild verwendet werden soll.'),
'        Falls das Bild rein dekorativ oder der entsprechende sichtbare Text bereits auf der Seite enthalten ist, sollte dieses Feld leer bleiben. Ein leeres Alt-Attribut wird dann angezeigt.',
unistr('        Wenn dieses Feld leer bleibt, k\00F6nnen Benutzer von assistiver Technologie wie Bildschirmsprachausgabe das Bild nicht wahrnehmen.'),
'        Falls das Bild nicht dekorativ ist, sollte der eingegebene Text kurz und beschreibend sein.',
unistr('        Dieser Text wird dann als alternativer Bildtext verwendet, und die Benutzer von Bildschirmsprachausgabe k\00F6nnen die Beschreibung h\00F6ren.</p>'),
unistr('        <p>Hinweis: Ein Bild gilt als dekorativ, wenn es keine wichtigen Inhalte pr\00E4sentiert oder wenn es zu gestalterischen oder nicht informativen Zwecken verwendet wird.</p>')))
,p_version_scn=>2564050
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106031954615661957)
,p_name=>'PE.PROPERTY.REGION_IMAGE_ALT_TEXT.PROMPT'
,p_message_language=>'de'
,p_message_text=>'Barrierefreie Beschreibung'
,p_version_scn=>2564050
);
