wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106185463596662003)
,p_name=>'PE.PROPERTY.SUCCESS_MESSAGE.COMPONENT_PROPERTY.PAGE_PROCESS.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie die Erfolgsmeldung f\00FCr diesen Prozess ein.'),
unistr('Wenn der Prozess ausgef\00FChrt wird und keinen Fehler generiert, wird diese Erfolgsmeldung f\00FCr den Prozess im Benachrichtigungsabschnitt der daraufhin angezeigten Ergebnisseite angezeigt.'),
unistr('Wenn Sie \00FCber eine URL-Umleitung eine Verzweigung zu einer anderen Seite vornehmen, m\00FCssen Sie m\00F6glicherweise das Attribut <em>Erfolgsmeldung beibehalten</em> aktivieren.</p>'),
unistr('<p>Bei mehrzeiligen Prozessen kann die folgende Ersetzungszeichenfolge verwendet werden, um die Anzahl der verarbeiteten Datens\00E4tze abzurufen:</p>'),
'<ul>',
unistr('  <li>Einf\00FCgen: <code>#MRI_COUNT#</code></li>'),
'  <li>Aktualisieren: <code>#MRU_COUNT#</code></li>',
unistr('  <li>L\00F6schen: <code>#MRD_COUNT#</code></li>'),
'</ul>',
unistr('<p>Beim Prozesstyp "E-Mail senden" kann die Ersetzungszeichenfolge <code>#TO#</code> verwendet werden, um die Empf\00E4nger der E-Mail zu ermitteln.</p>'),
unistr('<p>Plug-ins k\00F6nnen auch andere Ersetzungszeichenfolgen verwenden. Details dazu finden Sie in der Plug-in-Dokumentation.</p>')))
,p_version_scn=>2564067
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106335528883662048)
,p_name=>'PE.PROPERTY.SUCCESS_MESSAGE.HELP'
,p_message_language=>'de'
,p_message_text=>'Geben Sie den Text ein, der im Bereich "Benachrichtigung" (der als Teil des Seitentemplates definiert ist) angezeigt werden muss, wenn dieser Prozess erfolgreich abgeschlossen wird.'
