wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106677613341662151)
,p_name=>'PE.PROPERTY.TITLE.COMPONENT_PROPERTY.JET_CHART_AXES.HELP'
,p_message_language=>'de'
,p_message_text=>unistr('Geben Sie einen Titel f\00FCr die Achse ein. Der Titel beschreibt die Informationen, die auf der Achse Ihres Diagramms dargestellt werden.')
