wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(104995125054661631)
,p_name=>'PE.PROPERTY.TITLE.COMPONENT_PROPERTY.PAGE.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Seitentitel sind entscheidend, um Benutzern den Zweck einer Seite zu vermitteln, insbesondere solchen, die assistive Technologien wie Bildschirmsprachausgaben verwenden. Da der Seitentitel oft als Erstes von der Bildschirmsprachausgabe vorgelesen '
||unistr('wird, m\00FCssen Sie unbedingt aussagekr\00E4ftige und eindeutige Seitentitel verwenden.</p>'),
'<p>Best Practices:</p>',
'<ol>',
unistr('<li>Klar und aussagekr\00E4ftig:'),
unistr('Verwenden Sie spezifische Titel wie "Erl\00E4uterungen zu WCAG 2.1" oder Abschnittstitel f\00FCr die einfache Navigation.</li>'),
'<li>Effektiv:',
unistr('Beispiel: Geben Sie f\00FCr eine Formularseite relevante Informationen, wie den zu bearbeitenden Datensatz, an, z.B. "Kunden erstellen/bearbeiten: [Kundenname]". F\00FChren Sie dazu die folgenden Schritte in Page Designer aus:'),
'<ol>',
unistr('<li>W\00E4hlen Sie die Seite im Renderingbaum aus.</li>'),
unistr('<li>Suchen Sie im Eigenschaftseditor das Feld f\00FCr Identifizierung - Titel.</li>'),
'<li>Ersetzen Sie P1_CUSTOMER_NAME durch das entsprechende Seitenelement mit der Datensatz-ID.</li>',
unistr('<li>Geben Sie als Titelformat "Kunde erstellen/bearbeiten: &P1_CUSTOMER_NAME." ein (einschlie\00DFlich des Punktes).</li>'),
'</ol>',
'</li>',
'</ol>',
unistr('<p>Aussagekr\00E4ftige Seiten- und Regionstitel tragen wesentlich zu einer verbesserten Barrierefreiheit bei und erm\00F6glichen reibungslose Navigation sowie Inhaltsverst\00E4ndnis f\00FCr Benutzer verschiedener Webumgebungen.</p>')))
,p_version_scn=>2563853
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105618787848661815)
,p_name=>'PE.PROPERTY.TITLE.COMPONENT_PROPERTY.PAGE.HELP'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie einen Titel ein, der in der Titelleiste des Browserfensters angezeigt und f\00FCr Benutzer der Bildschirmsprachausgabe beim erstmaligen \00D6ffnen der Seite ausgegeben wird.'),
'        Die &PRODUCT_NAME.-Engine verwendet den angegebenen Titel anstelle der Ersetzungszeichenfolge <code>#TITLE#</code> im Seitentemplate. Dieser Titel wird zwischen die',
unistr('        HTML-Tags <code>&lt;TITLE&gt;</code> und <code>&lt;/TITLE&gt;</code> eingef\00FCgt.</p>'),
unistr('        <p>Ein Seitentitel sollte eine kurze und pr\00E4zise Beschreibung des Zwecks der Seite angeben, kann f\00FCr zus\00E4tzlichen Kontext den Anwendungsnamen und einen Unterabschnitt der Anwendung'),
unistr('        enthalten und muss die wichtigsten und eindeutigen Informationen stets zuerst nennen. Beispiel: Definieren Sie f\00FCr die Seite "Produkte" im Abschnitt "Administration" der Anwendung "Kundenportal"'),
'        den Seitentitel "Produkte | Administration | Kundenportal".</p>'))
,p_version_scn=>2563995
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105619422861661816)
