wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106690657795662155)
,p_name=>'UTR.HELP.P1'
,p_message_language=>'de'
,p_message_text=>unistr('Mit Theme Roller kann die Benutzeroberfl\00E4che Ihrer Anwendung einfach angepasst werden, indem Sie Farben ausw\00E4hlen und Formatvorlagen f\00FCr verschiedene Anwendungskomponenten festlegen k\00F6nnen. F\00FCr eine Anwendung kann eine beliebige Anzahl von Theme-Form')
||unistr('atvorlagen definiert werden. Die Anwendung wird jedoch nur mit der "aktuellen" Theme-Formatvorlage f\00FCr Endbenutzer angezeigt.')
,p_is_js_message=>true
,p_version_scn=>2564127
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(106690711073662155)
,p_name=>'UTR.HELP.P2'
,p_message_language=>'de'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Nachdem \00C4nderungen vorgenommen wurden, k\00F6nnen Attribute einfach wiederhergestellt werden, entweder f\00FCr die vollst\00E4ndige Theme-Formatvorlage durch Klicken auf die Schaltfl\00E4che "Zur\00FCcksetzen" oder durch Klicken auf das Symbol "Zur\00FCcksetzen" f\00FCr die Gru')
||'ppe. ',
'',
unistr('Bei Attributen, mit denen Vorder- und Hintergrundfarben ausgew\00E4hlt werden k\00F6nnen, enth\00E4lt das Kontrollk\00E4stchen vor den beiden Farbauswahloptionen Farbkontrastinformationen basierend auf den Web Content Accessibility Guidelines (WCAG) 2.0. Ein h\00F6herer')
||' berechneter Kontrastwert bedeutet, dass die Farbkombination barrierefreier ist.'))
,p_is_js_message=>true
,p_version_scn=>2564127
);
