wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105287987397661717)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION1'
,p_message_language=>'de'
,p_message_text=>unistr('Die Seiten-Sentry-Funktion gibt das boolesche Ergebnis der integrierten Pr\00FCfung f\00FCr die Sessionverifizierung an die Engine zur\00FCck. Wenn das Ergebnis TRUE lautet, wird die Engine die Seite weiterhin anzeigen oder akzeptieren. Wenn das Ergebnis FALSE l')
||unistr('autet, f\00FChrt die Engine eine Umleitung zur Seite f\00FCr die ung\00FCltige Session oder zur URL aus, die in diesem Authentifizierungsschema angegeben ist (siehe unten).')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105289245543661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION10'
,p_message_language=>'de'
,p_message_text=>unistr('Wenn die Seiten-Sentry-Funktion TRUE zur\00FCckgibt, wird mit dem Rendering bzw. der Verarbeitung der Seite fortgefahren. Wenn das Ergebnis FALSE lautet, muss die Engine beendet werden, weil im Authentifizierungsschema kein ung\00FCltiges Sessionziel angegeb')
||unistr('en ist. In diesem Fall wird die vom Benutzer zur Verf\00FCgung gestellte Seiten-Sentry-Funktion an eine Anmeldeseite au\00DFerhalb der %0-Umgebung umgeleitet, und zwar m\00F6glicherweise zu einem externen Authentifizierungsportal. Bei der Funktion muss au\00DFerdem ')
||'die globale Variable "g_unrecoverable_error := true" festgelegt sein, damit die Engine angewiesen wird, ohne Fehlermeldungsseite beendet zu werden.'
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105289335921661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION11'
,p_message_language=>'de'
,p_message_text=>unistr('Die Engine f\00FChrt folgenden Code aus, der als Prozess vor der Authentifizierung f\00FCr dieses Authentifizierungsschema angegeben wird:')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105289458808661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION12'
,p_message_language=>'de'
,p_message_text=>unistr('Dies wird als anonymer Block ausgef\00FChrt, der keinen Wert zur\00FCckgibt.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105289536610661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION13'
,p_message_language=>'de'
,p_message_text=>unistr('Es ist kein benutzerdefinierter Code f\00FCr die Ausf\00FChrung vor der Authentifizierung in diesem Schema angegeben.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105289758087661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION14'
,p_message_language=>'de'
,p_message_text=>unistr('Jede in der Anmelde-Form eingegebene Kombination aus Benutzername/Kennwort ist g\00FCltig. Der eingegebene Benutzername wird als Name f\00FCr den angemeldeten Benutzer w\00E4hrend der Dauer der Session verwendet. Diese Technik ist n\00FCtzlich, wenn Sie Ihre Anwendu')
||unistr('ng entwickeln, bevor tats\00E4chliche Benutzeraccounts eingerichtet sind.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105289881468661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION15'
,p_message_language=>'de'
,p_message_text=>unistr('\00DCberpr\00FCfen Sie den Benutzernamen und das Kennwort in dem Anmeldeformular mit den Angaben f\00FCr die Cookie User-Accounts von App Builder. Hierbei handelt es sich um dieselben Accounts, die von Ihrem Workspace f\00FCr die Anmeldung bei %0 verwendet werden. D')
||unistr('iese Technik ist n\00FCtzlich, wenn die Benutzer Ihrer Anwendung Entwickler sind, die %0 Accounts in derselben Datenbank und demselben Workspace haben.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105216399379661697)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION15A'
,p_message_language=>'de'
,p_message_text=>unistr('\00DCberpr\00FCfen Sie den Benutzernamen und das Kennwort in der Anmelde-Form mit den Angaben f\00FCr die Oracle-Datenbank-Accounts. Diese Technik ist n\00FCtzlich, wenn die Benutzer Ihrer Anwendung Accounts in der Datenbank haben.')
,p_version_scn=>2563926
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105289924196661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION16'
,p_message_language=>'de'
,p_message_text=>unistr('\00DCberpr\00FCfen Sie den Benutzernamen und Kennwort in der Anmelde-Form in Bezug auf das LDAP-Verzeichnis, das in diesem Authentifizierungsschema angegeben ist.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105290017729661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION17'
,p_message_language=>'de'
,p_message_text=>unistr('Die LDAP-Parameter sind folgenderma\00DFen gesetzt:')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105290702937661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION18'
,p_message_language=>'de'
,p_message_text=>unistr('F\00FChren Sie den folgenden benutzerdefinierten Code aus, um die Zugangsdaten zu \00FCberpr\00FCfen:')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105290951533661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION19'
,p_message_language=>'de'
,p_message_text=>unistr('\00DCberpr\00FCfen Sie, ob in der integrierten Sessiontabelle die Session enthalten ist, die von der integrierten Anmeldeseite verwendet wird. Wenn die Session vorhanden ist und noch keinem anderen Benutzer geh\00F6rt, legen Sie fest, dass sie jetzt dem berechti')
||unistr('gten Benutzer (\00FCber den Benutzernamen auf der Anmelde-Form) geh\00F6rt.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105288018740661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION2'
,p_message_language=>'de'
,p_message_text=>unistr('Die Seiten-Sentry-Funktion gibt das boolesche Ergebnis der integrierten Pr\00FCfung f\00FCr die Sessionverifizierung mit einer AND-Kombination des Ergebnisses der vom Benutzer angegebenen Pr\00FCfung f\00FCr die Sessionverifizierung an die Engine zur\00FCck. Wenn das Er')
||unistr('gebnis TRUE lautet, wird die Engine die Seite weiterhin anzeigen oder akzeptieren. Wenn das Ergebnis FALSE lautet, f\00FChrt die Engine eine Umleitung zur Seite f\00FCr das ung\00FCltige Sessionziel aus, das in diesem Authentifizierungsschema angegeben ist (sieh')
||'e unten).'
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105291025231661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION20'
,p_message_language=>'de'
,p_message_text=>unistr('Setzen Sie das Cookie %0 auf einen Wert, der die Zeile in der Tabelle f\00FCr die internen Sessions angibt.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105291129513661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION22'
,p_message_language=>'de'
,p_message_text=>'Bestimmen Sie, dass die URL beim Klick auf "Weiter" umgeleitet wird. Wenn ein "Deeplink" im Sessionzustand von der Rendering Engine erfasst wurde, verwenden Sie diesen als Navigations-URL. Navigieren Sie andernfalls zur URL, die als Home-Linkattribut'
||' der Anwendung angegeben ist.'
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105291327564661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION23'
,p_message_language=>'de'
,p_message_text=>unistr('Nach der Zugangsdatenverifizierung f\00FChrt die Engine folgenden Code aus, der als Prozess nach der Authentifizierung f\00FCr dieses Authentifizierungsschema angegeben wird:')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105291460594661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION24'
,p_message_language=>'de'
,p_message_text=>unistr('Dies wird als anonymer Block ausgef\00FChrt, der keinen Wert zur\00FCckgibt.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105291566496661719)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION25'
,p_message_language=>'de'
,p_message_text=>unistr('Es ist kein benutzerdefinierter Code f\00FCr die Ausf\00FChrung nach der Authentifizierung in diesem Schema angegeben.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105291616613661719)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION26'
,p_message_language=>'de'
,p_message_text=>unistr('F\00FChren Sie die Umleitung zum oben angegebenen URL aus. Dadurch wird das Ende der Anmeldungsverarbeitung mit der integrierten Anmeldeseite und den APIs, die diese Seite aufrufen, gekennzeichnet.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105288190220661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION3'
,p_message_language=>'de'
,p_message_text=>unistr('Verwenden Sie eine benutzerdefinierte Logik, um Seiten-Sentry-Aufgaben auszuf\00FChren. Die Engine f\00FChrt f\00FCr jede Seitenanforderung folgenden Code aus:')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105288255478661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION4'
,p_message_language=>'de'
,p_message_text=>unistr('Das boolesche Ergebnis des oben angegebenen Blocks wird an die Engine zur\00FCckgegeben. Wenn das Ergebnis TRUE lautet, wird die Engine die Seite weiterhin anzeigen oder akzeptieren. Wenn das Ergebnis FALSE lautet, f\00FChrt die Engine eine Umleitung zur Sei')
||unistr('te f\00FCr das ung\00FCltige Sessionziel aus, das in diesem Authentifizierungsschema angegeben ist (siehe unten).')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105288360351661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION5'
,p_message_language=>'de'
,p_message_text=>unistr('Die integrierte Methode f\00FCr die Sessionverifizierung ist f\00FCr den %0-Entwickler \00FCber den API-Aufruf verf\00FCgbar:')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105288468216661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION6'
,p_message_language=>'de'
,p_message_text=>unistr('Das Ergebnis dieser booleschen Funktion kann mit anderen Pr\00FCfungen in der vom Benutzer zur Verf\00FCgung gestellten Seiten-Sentry-Funktion in einem Authentifizierungsschema kombiniert werden. Beim Aufruf dieser API wird das Cookie %0 gepr\00FCft')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105288551375661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION7'
,p_message_language=>'de'
,p_message_text=>unistr('Wenn das Cookie vorhanden ist und der decodierte Wert eine Zeile in der Tabelle der internen Sessions ermittelt, ist die Session g\00FCltig, und es wird TRUE an die aufrufende Seiten-Sentry-Funktion zur\00FCckgegeben.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105288723679661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION8'
,p_message_language=>'de'
,p_message_text=>unistr('Wenn die Seiten-Sentry-Funktion TRUE zur\00FCckgibt, wird mit dem Rendering oder der Verarbeitung der Seite fortgefahren. Lautet das Ergebnis jedoch FALSE, ruft die Engine die Seite %0 auf, bei der es sich um die Anmeldeseite der Anwendung handelt, die a')
||unistr('ufgrund der Position im Authentifizierungsschema die ung\00FCltige Sessionseite ist.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105289103397661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION9'
,p_message_language=>'de'
,p_message_text=>unistr('Die Seiten-Sentry-Funktion gibt ein boolesches Ergebnis an die Engine zur\00FCck. Bei R\00FCckgabe von TRUE wird mit dem Rendering oder der Verarbeitung der Seite fortgefahren. Wenn das Ergebnis FALSE lautet, erfolgt seitens der Engine eine Umleitung zu %0.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105291711251661719)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.API_COMMON1'
,p_message_language=>'de'
,p_message_text=>unistr('In der Regel enth\00E4lt die Seite eine Anmelde-Form zum Erfassen der Zugangsdaten des Benutzers. Anschlie\00DFend wird nach den Weiterleitungsprozessen f\00FCr die Seite ein Authentifizierungsmodul zur \00DCberpr\00FCfung der Zugangsdaten aufgerufen. Nach der Authentif')
||unistr('izierung f\00FChrt die Seite Aufgaben f\00FCr die Sessionregistrierung und Cookieeinstellung aus. Abschlie\00DFend erfolgt eine Umleitung zur Startseite der Anwendung.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105291877749661719)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.API_COMMON2'
,p_message_language=>'de'
,p_message_text=>unistr('Die %0-API wwv_flow_custom_auth_std kann von derartigen Prozessen nach der Weiterleitung aufgerufen werden, um die oben beschriebenen Schritte auszuf\00FChren. Es stehen zwei Einstiegspunkte zur Verf\00FCgung:')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105291935539661719)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.API_COMMON3'
,p_message_language=>'de'
,p_message_text=>unistr('Rufen Sie die Anmeldeprozedur auf, damit die Engine alle Schritte ausf\00FChrt. Die Engine verwendet die integrierte Sessiontabelle und f\00FChrt die Aufgabe f\00FCr die Sessionregistrierung und Cookieeinstellung f\00FCr Sie aus. Wenn Sie benutzerdefinierten Code in')
||unistr(' dieses Authentifizierungsschema eingeben, wird dieser am Punkt vor der Authentifizierung, w\00E4hrend der Authentifizierung oder nach der Authentifizierung ausgef\00FChrt.')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105292007186661719)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.API_COMMON4'
,p_message_language=>'de'
,p_message_text=>unistr('Rufen Sie die Prozedur post_login auf, wenn Sie die Authentifizierung selbst ausf\00FChren und m\00F6chten, dass %0 die Prozesse nach der Authentifizierung f\00FCr Sie ausf\00FChrt. Sie k\00F6nnen mit diesen beiden Einstiegspunkten beliebige integrierte Schritte f\00FCr die')
||unistr(' Anmeldungsverarbeitung in Verbindung mit Ihrer eigenen Anmeldeseite und den Prozessen verwenden, die darauf ausgef\00FChrt werden. Wenn Sie die integrierten Prozesse nach der Authentifizierung verwenden, k\00F6nnen Sie auch vom Integrierten Seiten-Sentry- u')
||'nd Sessionverifizierungsprozess profitieren.'
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105288840283661718)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.BUILTIN_LOGIN_PG'
,p_message_language=>'de'
,p_message_text=>'die integrierte Anmeldeseite'
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105292198678661719)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.CHART_LOGIN1'
,p_message_language=>'de'
,p_message_text=>'Externe Anmeldungsverarbeitung'
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105292955222661719)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.CHART_LOGIN12'
,p_message_language=>'de'
,p_message_text=>unistr('Die Anmelde-URL %0 gibt keine %1-Anwendungsseite als ung\00FCltiges Sessionziel an. Au\00DFerdem befinden sich im Authentifizierungsschema keine Werte f\00FCr die Login-Verarbeitung. Auf dieser Seite werden folgende Schritte ausgef\00FChrt:')
,p_version_scn=>2563941
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(105293086865661719)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.CHART_LOGIN13'
,p_message_language=>'de'
