wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1493909354677201.4414)
,p_plugin_id=>wwv_flow_imp.id(1490801048649253.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>100
,p_static_id=>'result_row_template'
,p_prompt=>'Ergebniszeilentemplate'
,p_attribute_type=>'HTML'
,p_is_required=>true
,p_is_translatable=>true
,p_depending_on_attribute_id=>wwv_flow_imp.id(1493694522672314.4414)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'Y'
,p_attribute_group_id=>wwv_flow_imp.id(6038497365653879)
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Beispiel: Template zum Rendern des Standardlayouts f\00FCr Suchergebnisse.</p>'),
'<pre>',
'&lt;div class="a-ResultsItem &amp;RESULT_CSS_CLASSES!ATTR."&gt;',
'  {if ?ICON_VALUE/}',
'    {case ICON_TYPE/}',
'      {when INITIALS/}',
'        &lt;div class="a-ResultItem-initials u-color-var"&gt;&amp;ICON_VALUE.&lt;/div&gt;',
'      {when URL/}',
'        &lt;div class="a-ResultItem-image"&gt;&lt;img src="&amp;ICON_VALUE!ATTR." alt="&amp;TITLE!ATTR." role="presentation" /&gt;&lt;/div&gt;',
'      {when CLASS/}',
'        &lt;div class="a-ResultItem-icon u-color-var"&gt;&lt;span class="fa &amp;ICON_VALUE!ATTR." aria-hidden="true"&gt;&lt;/span&gt;&lt;/div&gt;',
'    {endcase/}',
'  {endif/}',
'  &lt;div class="a-ResultsItem-content"&gt;',
'    &lt;div class="a-ResultsItem-header"&gt;',
'      {if ?LINK/}',
'        &lt;span class="a-ResultsItem-title"&gt;&lt;a href="&amp;LINK!ATTR."&gt;&amp;TITLE.&lt;/a&gt;&lt;/span&gt;',
'      {else/}',
'        &lt;span class="a-ResultsItem-title"&gt;&amp;TITLE.&lt;/span&gt;',
'      {endif/}',
'      {if ?BADGE/}&lt;span class="a-ResultsItem-badge"&gt;&amp;BADGE.&lt;/span&gt;{endif/}',
'    &lt;/div&gt;',
'    {if ?SUBTITLE/}&lt;div class="a-ResultsItem-subTitle"&gt;&amp;SUBTITLE.&lt;/div&gt;{endif/}',
'    {if ?DESCRIPTION/}&lt;div class="a-ResultsItem-description"&gt;&amp;DESCRIPTION.&lt;/div&gt;{endif/}',
'    {if ?HAS_CUSTOM_ATTRS/}',
'      &lt;div class="a-ResultsItem-attributes"&gt;',
'        {if ?CUSTOM_01/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_01.&lt;/span&gt;{endif/}',
'        {if ?CUSTOM_02/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_02.&lt;/span&gt;{endif/}',
'        {if ?CUSTOM_03/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;CUSTOM_03.&lt;/span&gt;{endif/}',
'      &lt;/div&gt;',
'    {endif/}',
'    {if ?LAST_MODIFIED/}&lt;div class="a-ResultsItem-misc"&gt;&amp;LAST_MODIFIED.&lt;/div&gt;{endif/}',
'  &lt;/div&gt;',
'&lt;/div&gt;',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Geben Sie zum Anzeigen einer Suchergebniszeile einen HTML-Ausdruck ein. Mit der <code>&COLUMN.</code>-Syntax werden Spaltenwerte der Suchergebnisse in HTML angezeigt. Unterst\00FCtzt Templatedirektiven. Die folgenden Ersetzungen sind verf\00FCgbar:'),
'</p>',
'<dl>',
'<dt>TITLE</dt>',
'Spalte <dd><strong>Titel</strong>.</dd>',
'<dt>SUBTITLE</dt>',
'Spalte <dd><strong>Untertitel</strong>.</dd>',
'<dt>PRIMARY_KEY_1</dt>',
unistr('Spalte <dd><strong>Prim\00E4rschl\00FCssel</strong>.</dd>'),
'<dt>PRIMARY_KEY_2</dt>',
unistr('<dd>Zweite Spalte <strong>Prim\00E4rschl\00FCssel</strong>.</dd>'),
'<dt>DESCRIPTION</dt>',
'<dd>Spalte <strong>Beschreibung</strong>.</dd>',
'<dt>BADGE</dt>',
'<dd>Spalte <strong>Badge</strong>.</dd>',
'<dt>LAST_MODIFIED</dt>',
unistr('<dd>Spalte <strong>Zuletzt ge\00E4ndert am</strong>. Sofern angegeben, wird die <strong>Formatmaske "Zuletzt ge\00E4ndert am"</strong> auf diese Spalte angewendet.</dd>'),
'<dt>CUSTOM_01</dt>',
'<dd>Spalte <strong>Benutzerdefiniert 1</strong>.</dd>',
'<dt>CUSTOM_02</dt>',
'<dd>Spalte <strong>Benutzerdefiniert 2</strong>.</dd>',
'<dt>CUSTOM_03</dt>',
'<dd>Spalte <strong>Benutzerdefiniert 3</strong>.</dd>',
'<dt>SCORE</dt>',
unistr('<dd>Spalte <strong>Bewertung</strong>. Bei Oracle TEXT-Suchkonfigurationen ist dies die Bewertung, die von Oracle TEXT zur\00FCckgegeben wird. Bei anderen Konfigurationen k\00F6nnen Sie eine Abfragespalte zuordnen.</dd>'),
'<dt>ICON_TYPE</dt>',
'<dd>Stellt den Symboltyp dar: Kann <strong>CLASS</strong>, <strong>URL</strong> oder <strong>INITIALS</strong> sein.</dd>',
'<dt>ICON_VALUE</dt>',
unistr('<dd>Der tats\00E4chliche Symbolwert, je nach Wert von <strong>ICON_TYPE</strong></dd>'),
'<dt>RESULT_CSS_CLASSES</dt>',
'<dd>Die auf jedes Ergebnis angewendeten CSS-Klassen, basierend auf dem Suchkonfigurationsattribut <strong>Ergebnis-CSS-Klassen</strong>.</dd>',
'<dt>LINK</dt>',
'<dd>Der in der Suchkonfiguration angegebene <strong>Link</strong>.</dd>',
'<dt>CONFIG_ID</dt>',
'<dd>Interne ID der Suchkonfiguration.</dd>',
'<dt>CONFIG_LABEL</dt>',
'<dd>Label der Suchkonfiguration.</dd>',
'</dl>'))
);
