wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1727004690548379.4414)
,p_plugin_id=>wwv_flow_imp.id(1700838675352758.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>13
,p_display_sequence=>135
,p_static_id=>'match_vector_item'
,p_prompt=>unistr('\00DCbereinstimmungsvektorelement')
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>false
,p_is_translatable=>false
,p_attribute_group_id=>wwv_flow_imp.id(6282574537711753)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>W\00E4hlen Sie ein Seitenelement aus, an das der Geocoder den <em>\00DCbereinstimmungsvektor</em> zur\00FCckgibt. Der \00DCbereinstimmungsvektor ist eine 17-stellige Zeichenfolge mit detaillierten Informationen dazu, wie jedes Adressattribut den zum Geocoding ver')
||'wendeten Daten zugeordnet wurde.</p>',
unistr('<p><strong>Die Ziffern des \00DCbereinstimmungsvektors k\00F6nnen die folgenden Werte aufweisen:</strong></p>'),
'<ul>',
'<li><p>0: Das Eingabeattribut ist nicht Null und wird einem Wert ungleich Null zugeordnet.</p></li>',
'<li><p>1: Das Eingabeattribut ist Null und wird einem Nullwert zugeordnet.</p></li>',
'<li><p>2: Das Eingabeattribut ist nicht Null und wird durch einen anderen Wert ungleich Null ersetzt.</p></li>',
'<li><p>3: Das Eingabeattribut ist nicht Null und wird durch einen Nullwert ersetzt.</p></li>',
'<li><p>4: Das Eingabeattribut ist Null und wird durch einen Wert ungleich Null ersetzt.</p></li>',
'</ul>',
'<br>',
unistr('<p><strong>\00DCbereinstimmungsvektorziffern und das Adressattribut entsprechen den folgenden Elementen:</strong></p>'),
'<ul>',
unistr('<li><p>3: Adresspunkt (genaue Adresse mit \00DCbereinstimmung in den zum Geocoding verwendeten Daten)</p></li>'),
unistr('<li><p>4: Name f\00FCr den jeweiligen Ort von Interesse</p></li>'),
'<li><p>5: Hausnummer</p></li>',
unistr('<li><p>6: Stra\00DFenpr\00E4fix</p></li>'),
unistr('<li><p>7: Stra\00DFenname</p></li>'),
unistr('<li><p>8: Stra\00DFensuffix</p></li>'),
unistr('<li><p>9: Stra\00DFentyp</p></li>'),
unistr('<li><p>10: Sekund\00E4re Einheit</p></li>'),
'<li><p>11: Ort</p></li>',
'<li><p>14: Region</p></li>',
'<li><p>15: Land</p></li>',
'<li><p>16: Postleitzahl</p></li>',
unistr('<li><p>17: Erg\00E4nzende Postleitzahl</p></li>'),
'<li><p><em>Andere Ziffern werden noch nicht verwendet.</em></p></li>',
'</ul>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1727549870549765.4414)
,p_plugin_id=>wwv_flow_imp.id(1700838675352758.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>14
,p_display_sequence=>140
,p_static_id=>'trigger_geocoding'
,p_prompt=>unistr('Geocoding ausl\00F6sen')
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'AUTOMATIC'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>unistr('<p>Bestimmen Sie, wann das Geocoding ausgel\00F6st werden soll. Dabei f\00FChrt der Browser die REST-Anforderung an den Geocoding-Service aus und zeigt das Popup-Fenster mit m\00F6glichen \00DCbereinstimmungen an.</p>')
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1728048005551626.4414)
,p_plugin_attribute_id=>wwv_flow_imp.id(1727549870549765.4414)
,p_display_sequence=>10
,p_display_value=>'Automatisch'
,p_return_value=>'AUTOMATIC'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geocoding wird automatisch ausgel\00F6st, bevor die Seite weitergeleitet wird.</p>'),
unistr('<p>Wenn ein abh\00E4ngiger Elementwert ge\00E4ndert wurde, z.B. der Wert von <em>P1_STREET</em>, und Geocoding noch nicht ausgef\00FChrt oder keine g\00FCltige Adresse ausgew\00E4hlt wurde, wird sichergestellt, dass Geocoding automatisch ausgel\00F6st wird. In diesem Fall w')
||unistr('ird der Weiterleitungsfluss der aktuellen Seitenweiterleitung unterbrochen und zun\00E4chst ein Popup-Fenster mit m\00F6glichen \00DCbereinstimmungen angezeigt. Wenn der Benutzer eine der \00DCbereinstimmungen ausw\00E4hlt, kann die Seite ohne weitere Unterbrechung weit')
||'ergeleitet werden.</p>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1728439221554365.4414)
,p_plugin_attribute_id=>wwv_flow_imp.id(1727549870549765.4414)
,p_display_sequence=>20
,p_display_value=>'Dynamische Aktion'
,p_return_value=>'DYNAMIC_ACTION'
,p_help_text=>unistr('<p>Geocoding muss ausgel\00F6st werden, indem Sie die dynamische Aktion <em>Geocoding ausl\00F6sen</em> zur Seite hinzuf\00FCgen.</p>')
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(1728803167561342.4414)
,p_plugin_attribute_id=>wwv_flow_imp.id(1727549870549765.4414)
,p_display_sequence=>30
,p_display_value=>'jQuery-Selektor'
,p_return_value=>'JQUERY_SELECTOR'
,p_help_text=>unistr('<p>Geocoding wird basierend auf einem Ereignis im DOM-Element des Selektors ausgel\00F6st. Wenn ein Eingabefeld referenziert wird, wird Geocoding bei einer <em>\00C4nderung</em> des Elements ausgel\00F6st. Wenn eine Schaltfl\00E4che referenziert wird, wird Geocoding')
||unistr(' <em>beim Klicken</em> ausgel\00F6st.</p>')
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(1747463542804307.4414)
,p_plugin_id=>wwv_flow_imp.id(1700838675352758.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>15
,p_display_sequence=>150
,p_static_id=>'trigger_geocoding_selector'
,p_prompt=>'Selektor'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_supported_component_types=>'APEX_APPLICATION_PAGE_ITEMS'
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1727549870549765.4414)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'JQUERY_SELECTOR'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Prozess ausf\00FChren, wenn Elemente <em>P1_STREET</em> und <em>P1_ZIP_CODE</em> sich \00E4ndern, jQuery-Selektor:</p>'),
'<pre>',
'#P1_STREET,#P1_ZIP_CODE',
'</pre>'))
,p_help_text=>unistr('<p>Geben Sie den jQuery-Selektor an, der das Element referenziert, das das Geocoding ausl\00F6st. Schaltfl\00E4chen l\00F6sen Geocoding <em>beim Klicken</em> aus. Andere Elemente l\00F6sen es <em>bei \00C4nderung</em> aus.</p>')
);
wwv_flow_imp_shared.create_plugin_event(
 p_id=>wwv_flow_imp.id(12982963519254231.4414)
