'    when ''U'' then',
'        update emp',
'           set ename  = :P1_ENAME,',
'               deptno = :P1_DEPTNO',
'         where rowid  = :P1_ROWID;',
'    when ''D'' then',
'        delete emp',
'         where rowid = :P1_ROWID;',
'    end case;',
'end;',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
