prompt --application/shared_components/plugins/process_type/geocoding
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(23280737050223902.4414)
,p_plugin_type=>'PROCESS TYPE'
,p_name=>'GEOCODING'
,p_display_name=>'Serverseitiges Geocoding'
,p_supported_component_types=>'APEX_APPLICATION_PAGE_PROC:APEX_APPL_AUTOMATION_ACTIONS:APEX_APPL_TASKDEF_ACTIONS:APEX_APPL_WORKFLOW_ACTIVITIES'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('PROCESS TYPE','GEOCODING'),'')
,p_api_version=>2
,p_substitute_attributes=>true
,p_version_scn=>82123644
,p_subscribe_plugin_settings=>true
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Dieser Prozesstyp bietet Geocoding-Funktionalit\00E4t (Umwandlung einer Postadresse in eine Koordinate).</p>'),
unistr('<p>Geocoding wird durch Aufruf von <strong>SDO_GCDR.ELOC_GEOCODE</strong> ausgef\00FChrt, wodurch eine REST-Anforderung an den <strong>Oracle Elocation</strong>-Geocoding-Service (elocation.oracle.com) gesendet wird. Weitere Informationen zu dieser Funkt')
||'ion finden Sie in der <strong>Oracle Spatial-Entwicklerdokumentation</strong>.',
'',
unistr('<p>Die Geocoding-Eingabedaten stammen aus Seitenelementen, die Adressteilen wie Stra\00DFe, Hausnummer, Postleitzahl oder Ort zugeordnet sind. Der Prozess f\00FCllt ein Koordinaten- und \00DCbereinstimmungsvektor-Seitenelement mit den Ergebnissen der ersten \00FCber')
||unistr('einstimmenden Adresse auf. Au\00DFerdem k\00F6nnen alle \00DCbereinstimmungen zur weiteren Verarbeitung in eine Collection geladen werden. Wenn <strong>Adresse bereinigen</strong> aktiviert ist, werden Adressteil-Seitenelemente mit den bereinigten Werten der ers')
||unistr('ten \00FCbereinstimmenden Adresse \00FCberschrieben.</p>'),
'',
unistr('<p>Hinweis: Dieser Prozesstyp wird nur auf Oracle Autonomous Database unterst\00FCtzt.</p>')))
,p_version_identifier=>'1.0'
);
wwv_flow_imp_shared.create_plugin_attr_group(
 p_id=>wwv_flow_imp.id(6274597128526118.4414)
,p_plugin_id=>wwv_flow_imp.id(23280737050223902.4414)
,p_title=>'Geocoding-Eingabe'
,p_display_sequence=>10
);
wwv_flow_imp_shared.create_plugin_attr_group(
