,p_display_sequence=>50
,p_display_value=>'Postleitzahl lockern'
,p_return_value=>'RELAX_POSTAL_CODE'
,p_help_text=>unistr('<p>Die Postleitzahl (sofern angegeben), der Stra\00DFenname, der Stra\00DFentyp und die Hausnummer k\00F6nnen sich von den zum Geocoding verwendeten Daten unterscheiden.</p>')
);
wwv_flow_imp_shared.create_plugin_attr_value(
