wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(23299513762315037.4414)
,p_plugin_id=>wwv_flow_imp.id(23280737050223902.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>14
,p_display_sequence=>140
,p_prompt=>unistr('\00DCbereinstimmungsvektorelement')
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>false
,p_is_translatable=>false
,p_attribute_group_id=>wwv_flow_imp.id(6274942011526119)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>W\00E4hlen Sie ein Seitenelement aus, um den <em>\00DCbereinstimmungsvektor</em> der <em>ersten Geocoder-\00DCbereinstimmung</em> zu speichern. Der \00DCbereinstimmungsvektor ist eine 17-stellige Zeichenfolge mit detaillierten Informationen dazu, wie jedes Adress')
||'attribut den zum Geocoding verwendeten Daten zugeordnet wurde.</p>',
unistr('<p><strong>Die Ziffern des \00DCbereinstimmungsvektors k\00F6nnen die folgenden Werte aufweisen:</strong></p>'),
'<ul>',
'<li><p>0: Das Eingabeattribut ist nicht Null und wird einem Nicht-Nullwert zugeordnet.</p></li>',
'<li><p>1: Das Eingabeattribut ist Null und wird einem Nullwert zugeordnet.</p></li>',
'<li><p>2: Das Eingabeattribut ist nicht Null und wird durch einen anderen Nicht-Nullwert ersetzt.</p></li>',
'<li><p>3: Das Eingabeattribut ist nicht Null und wird durch einen Nullwert ersetzt.</p></li>',
'<li><p>4: Das Eingabeattribut ist Null und wird durch einen Nicht-Nullwert ersetzt.</p></li>',
'</ul>',
'<br>',
unistr('<p><strong>Die Ziffern des \00DCbereinstimmungsvektors und das Adressattribut entsprechen den folgenden Elementen:</strong></p>'),
'<ul>',
unistr('<li><p>3: Adresspunkt (genaue Adresse mit \00DCbereinstimmung in den zum Geocoding verwendeten Daten)</p></li>'),
unistr('<li><p>4: Name f\00FCr den jeweiligen Ort von Interesse</p></li>'),
'<li><p>5: Hausnummer</p></li>',
unistr('<li><p>6: Stra\00DFenpr\00E4fix</p></li>'),
unistr('<li><p>7: Stra\00DFenname</p></li>'),
unistr('<li><p>8: Stra\00DFensuffix</p></li>'),
unistr('<li><p>9: Stra\00DFentyp</p></li>'),
unistr('<li><p>10: Sekund\00E4re Einheit</p></li>'),
'<li><p>11: Ort</p></li>',
'<li><p>14: Region</p></li>',
'<li><p>15: Land</p></li>',
'<li><p>16: Postleitzahl</p></li>',
unistr('<li><p>17: Erg\00E4nzende Postleitzahl</p></li>'),
'<li><p><em>Andere Ziffern werden noch nicht verwendet.</em></p></li>',
'</ul>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(23312282210252045.4414)
,p_plugin_id=>wwv_flow_imp.id(23280737050223902.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>15
,p_display_sequence=>150
,p_prompt=>'Collection-Name'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_display_length=>30
,p_max_length=>30
,p_is_translatable=>false
,p_attribute_group_id=>wwv_flow_imp.id(6274942011526119)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Wenn der Name einer Collection angegeben wird, werden alle Geocoding-Ergebnisse in diese Collection abgerufen. Die Zuordnung der Geocoding-Ergebnisattribute zu Collection-Member-Attributen ist wie folgt festgelegt:</p>',
'<ul>',
unistr('<li><code>C001</code>: <strong>Stra\00DFe</strong></li>'),
'<li><code>C002</code>: <strong>Hausnummer</strong></li>',
'<li><code>C003</code>: <strong>Postleitzahl</strong></li>',
'<li><code>C004</code>: <strong>Ort</strong></li>',
'<li><code>C005</code>: <strong>Ortsteil</strong></li>',
'<li><code>C006</code>: <strong>Region (Bundesland)</strong></li>',
'<li><code>C007</code>: <strong>Land</strong></li>',
unistr('<li><code>C011</code>: <strong>\00DCbereinstimmungsvektor</strong></li>'),
unistr('<li><code>N001</code>: <strong>L\00E4ngengrad</strong></li>'),
'<li><code>N002</code>: <strong>Breitengrad</strong></li>',
'<li><code>D001</code>: <strong>Geocoding-Zeitstempel</strong></li>',
'</ul>',
'<p>Verwenden Sie die folgende Abfrage, um Geocoding-Ergebnisse aus der Collection abzurufen:</p>',
'',
'<pre>',
'select c001 as street,',
'       c002 as house_number,',
'       c003 as postal_code,',
'       c004 as city,',
'       c005 as city_sub_area,',
'       c006 as region,',
'       c007 as country,',
'       c011 as match_vector,',
'       n001 as longitude,',
'       n002 as latitude,',
'       d001 as geocode_date',
'  from apex_collections',
' wobei collection_name = ''{Collection-Name}''',
'</pre>',
unistr('<p>Wenn die Collection nicht vorhanden ist, wird sie erstellt, bevor das erste Member hinzugef\00FCgt wird. Vorhandene Collections werden <em>nicht</em> gel\00F6scht. Dies muss mit einem separaten Seitenprozess erfolgen, der vor dem Geocoding-Prozess ausgef\00FC')
||'hrt wird.</p>'))
);
end;
/
