,p_plugin_type=>'DYNAMIC ACTION'
,p_name=>'JAVASCRIPT_CODE'
,p_display_name=>unistr('JavaScript-Code ausf\00FChren')
,p_category=>'EXECUTE'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('DYNAMIC ACTION','JAVASCRIPT_CODE'),'')
,p_api_version=>1
,p_standard_attributes=>'ITEM:BUTTON:REGION:JQUERY_SELECTOR:JAVASCRIPT_EXPRESSION:TRIGGERING_ELEMENT:EVENT_SOURCE'
,p_substitute_attributes=>true
,p_version_scn=>72472667
,p_subscribe_plugin_settings=>true
,p_is_quick_pick=>true
,p_help_text=>unistr('Mit dieser Funktion k\00F6nnen Sie benutzerdefinierten, seitenspezifischen JavaScript-Code definieren oder aufrufen, der innerhalb des dynamischen Aktions-Frameworks verwendet werden soll. Wenn Sie JavaScript-Code definieren, der nur f\00FCr eine Seite spezi')
||unistr('fisch ist, k\00F6nnen Sie ihn mit dem Attribut <em>Funktion und globale Variablendeklaration</em> auf Seitenebene definieren. Dort definierte Funktionen und Variablen k\00F6nnen dann mit dieser Aktion referenziert werden.')
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(258539816972931512.4414)
,p_plugin_id=>wwv_flow_imp.id(258538732294917000.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Code'
,p_attribute_type=>'JAVASCRIPT'
,p_is_required=>true
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Dieser Code greift auf die folgenden zu der dynamischen Aktion geh\00F6rigen Attribute zu:</p>'),
'<dl>',
'  <dt><code>this.triggeringElement</code></dt>',
unistr('    <dd>Eine Referenz auf das DOM-Objekt des Elements, das die dynamische Aktion ausgel\00F6st hat.</dd>'),
'  <dt><code>this.affectedElements</code></dt>',
unistr('    <dd>Ein jQuery-Objekt, das alle betroffenen Elemente enth\00E4lt.</dd>'),
'  <dt><code>this.action</code></dt>',
unistr('    <dd>Das Aktionsobjekt, das Details enth\00E4lt, wie den Aktionsnamen und zus\00E4tzliche Attributwerte.</dd>'),
'  <dt><code>this.browserEvent</code></dt>',
unistr('     <dd>Das Ereignisobjekt des Ereignisses, das das Ereignis ausgel\00F6st hat. Hinweis: Beim Laden entspricht dies ''load''.</dd>'),
'  <dt><code>this.data</code></dt>',
unistr('    <dd>Optionale zus\00E4tzliche Daten, die vom Event Handler \00FCbergeben werden k\00F6nnen.</dd>'),
'</dl>'))
,p_help_text=>unistr('Geben Sie ein beliebiges, benutzerdefiniertes JavaScript ein, das f\00FCr die Seite oder dynamische Aktion spezifisch ist.')
