,p_show_in_wizard=>false
,p_default_value=>'Y'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>W\00E4hlen Sie, ob jede Zeile, die aktualisiert oder gel\00F6scht werden soll, in der zugrunde liegenden Tabelle gesperrt wird, bevor die Zeile verarbeitet wird.</p>'),
unistr('<p>Hinweis: Das Sperren von Zeilen ist <em>nicht verf\00FCgbar</em> f\00FCr interaktive Grid-Regionen, die eine <strong>REST-Datenquelle</strong> und den <strong>Zieltyp</strong> <strong>Tabelle/View</strong> oder <strong>PL/SQL-Code</strong> verwenden.</p>')))
);
