prompt --application/shared_components/plugins/authentication_type/custom
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(352953211423309033.4414)
,p_plugin_type=>'AUTHENTICATION TYPE'
,p_name=>'CUSTOM'
,p_display_name=>'Benutzerdefiniert'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('AUTHENTICATION TYPE','CUSTOM'),'')
,p_api_version=>1
,p_standard_attributes=>'INVALID_SESSION:LOGIN_PAGE'
,p_substitute_attributes=>true
,p_version_scn=>72472667
,p_subscribe_plugin_settings=>true
,p_help_text=>unistr('Ein Authentifizierungsschema, mit dem Sie Ihre eigenen PL/SQL-Funktionen zur Bestimmung der Benutzerauthentifizierung definieren k\00F6nnen.')
,p_version_identifier=>'1.0'
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(353179625368369848.4414)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_prompt=>'Sentry-Funktionsname'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Gibt PL/SQL-Code, der einen booleschen Wert zur\00FCckgibt, in dem ''PL/SQL-Code'' an -</p>'),
'<pre>',
'function sentry_basic_auth',
'return boolean',
'is',
'    c_auth_header   constant varchar2(4000) := owa_util.get_cgi_env(''AUTHORIZATION'');',
'    l_user_pass     varchar2(4000);',
'    l_separator_pos pls_integer;',
'begin',
'    if apex_application.g_user <> ''nobody'' then',
'        return true;',
'    end if;',
'',
'    if c_auth_header like ''Basic %'' then',
'        l_user_pass := utl_encode.text_decode (',
'                           buf      => substr(c_auth_header, 7),',
'                           encoding => utl_encode.base64 );',
'        l_separator_pos := instr(l_user_pass, '':'');',
'        if l_separator_pos > 0 then',
'            apex_authentication.login (',
'                p_username => substr(l_user_pass, 1, l_separator_pos-1),',
'                p_password => substr(l_user_pass, l_separator_pos+1) );',
'            return true;',
'        end if;',
'    end if;',
'',
'    return false;',
'end sentry_basic_auth;',
'</pre>',
'<p>Gibt eine PL/SQL-Datenbankfunktion an - </p>',
'<pre>',
'sentry_basic_auth',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie den Namen einer Funktion ein, die von der &PRODUCT_NAME. Engine zu Beginn einer an die Engine gestellten Anforderung, wie "Vor Anzeige oder Verarbeitung jeder Seite", oder bei der Ausgabe einer AJAX-Anforderung ausgef\00FChrt wird. '),
'Sie kann im PL/SQL-Code der Authentifizierung, innerhalb eines Packages oder als gespeicherte Funktion definiert werden. </p>',
unistr('<p>Wenn diese Funktion False zur\00FCckgibt (was m\00F6glicherweise bedeutet, dass der Benutzer nicht angemeldet ist), wird die Session als nicht g\00FCltig markiert und die <em>ung\00FCltige Sessionprozedur</em> wird aufgerufen.'),
unistr('Danach nimmt &PRODUCT_NAME. eine Umleitung zu der URL vor, die in "Session nicht g\00FCltig > Gehe zu" definiert wird.'),
'Wenn der Wert dieses Feldes leer ist,',
unistr('wird eine interne Standard-Sentry-Funktion aufgerufen, die versucht eine g\00FCltige Session aufzubauen, indem die Session-ID in der URL und die Sessioninformationen in dem Cookie des Authentifizierungsschemas verglichen werden (mit einem Fallback zu dem')
||unistr(' &PRODUCT_NAME. Builder-Cookie, falls dieser Vorgang nicht erfolgreich verl\00E4uft).</p>')))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(551983430308015470.4414)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>2
,p_display_sequence=>20
,p_prompt=>unistr('Ung\00FCltiger Sessionprozedurname')
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'procedure invalid_session_basic_auth',
'is',
'begin',
'    owa_util.status_line (',
'        nstatus       => 401,',
'        creason       => ''Basic Authentication required'',',
'        bclose_header => false);',
'    htp.p(''WWW-Authenticate: Basic realm="protected realm"'');',
'    apex_application.stop_apex_engine;',
'end invalid_session_basic_auth;',
'</pre>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie den Namen einer PL/SQL-Prozedur ein, die aufgerufen wird, wenn eine ung\00FCltige Session ermittelt wurde.</p>'),
'',
'<p>Sie kann eine Funktion des anonymen PL/SQL-Codeblocks, eine Packagefunktion oder eine Standalone-Funktion in der Datenbank referenzieren. Beispiel: <code>invalid_session_basic_auth</code><p/>',
'',
unistr('<p>Wenn Sie eine PL/SQL-Datenbankpackage- oder eine Standalone-Funktion referenzieren, k\00F6nnen Sie die Ersetzungszeichenfolge <code>#OWNER#</code> zum Referenzieren des Parsingschemas der aktuellen Anwendung verwenden. Beispiel: <code>#OWNER#.invalid_')
||'session_basic_auth</code>.'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(353293115026395181.4414)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'Authentifizierungsfunktionsname'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Geben Sie den folgenden Code in den Textbereich ''PL/SQL-Code'' ein</p>',
'<pre>',
'function my_authentication (',
'    p_username in varchar2,',
'    p_password in varchar2 )',
'    return boolean',
'is',
'    l_user my_users.user_name%type := upper(p_username);',
'    l_id   my_users.id%type;',
'    l_hash my_users.password_hash%type;',
'begin',
'    begin',
'        select id  , password_hash',
'          into l_id, l_hash',
'          from my_users',
'         where user_name = l_user;',
'    exception when no_data_found then',
'        l_hash := ''-invalid-'';',
'    end;',
'',
'    return l_hash = rawtohex(sys.dbms_crypto.hash (',
'                        sys.utl_raw.cast_to_raw (',
'                            p_password||l_id||l_user ),',
'                        sys.dbms_crypto.hash_sh512 ));',
'end;',
'</pre>',
'',
'<p>und <code>my_authentication</code> als "Authentifizierungsfunktion".'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie den Namen der Funktion ein, die den Benutzernamen und das Kennwort des Benutzers pr\00FCft, nachdem diese auf einer Anmeldeseite eingegeben wurden.'),
unistr('Wenn keine Eingabe vorgenommen wird, werden Benutzername und Kennwort als g\00FCltig betrachtet.'),
'Die Funktion kann im Textbereich des PL/SQL-Codes der Authentifizierung innerhalb eines Packages oder als gespeicherte Funktion definiert werden.</p>',
'',
unistr('<p>Diese Funktion muss einen booleschen Wert an die Anmeldeprozedur zur\00FCckgeben, die sie aufruft. Sie enth\00E4lt 2 Eingabeparameter ''p_username'' und ''p_password'', mit denen auf die Werte zugegriffen werden kann, die ein Endbenutzer in die Anmeldeseite e')
||'ingegeben hat.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(353301225415398269.4414)
,p_plugin_id=>wwv_flow_imp.id(352953211423309033.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>4
,p_display_sequence=>40
,p_prompt=>'Post-Abmelde-Prozedurname'
,p_attribute_type=>'TEXT'
,p_is_required=>false
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Gibt den folgenden Code in den Textbereich ''PL/SQL-Code'' ein</p>',
'<pre>',
'procedure my_post_logout',
'is',
'begin',
'    insert into logout_log (',
'        application_id,',
'        session_id,',
'        logout_time,',
'        user_name',
'    ) values (',
'        :APP_ID,',
'        :APP_SESSION,',
'        sysdate,',
'        :APP_USER );',
'end;',
'</pre>',
'',
'<p>sowie <code>my_post_logout</code> als ''Post-Abmeldeprozedur''.</p>'))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Der Name der Prozedur, die aufgerufen wird, nachdem der Endbenutzer auf die Abmelde-URL geklickt hat. Er kann f\00FCr das Logging verwendet werden.'),
'Die Prozedur selbst kann im Textbereich des PL/SQL-Codes der Authentifizierung, innerhalb eines Packages oder als gespeicherte Funktion definiert werden.'))
);
