wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(361805328759939092.4414)
,p_plugin_id=>wwv_flow_imp.id(361799714569626543.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_prompt=>'Zeilenversionsspalte'
,p_attribute_type=>'COLUMN'
,p_is_required=>false
,p_is_common=>false
,p_max_length=>128
,p_column_data_types=>'VARCHAR2:NUMBER:DATE:TIMESTAMP:TIMESTAMP_TZ:TIMESTAMP_LTZ:INTERVAL_Y2M:INTERVAL_D2S'
,p_is_translatable=>false
,p_parent_attribute_id=>wwv_flow_imp.id(361800327927635543.4414)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>W\00E4hlen Sie die Spalte, die die Zeilenversion identifiziert. Diese Spalte muss auf der Seite nicht vorhanden sein. Lassen Sie dieses Attribut leer, um die integrierte Pr\00FCfsumme zu verwenden.</p>'),
unistr('<p>Die opportunistische Sperre verwendet die Ermittlung von verlorenen Updates, um die Datenintegrit\00E4t in Anwendungen sicherzustellen, bei denen nebenl\00E4ufig auf Daten zugegriffen werden kann. &PRODUCT_NAME. kann eine integrierte Pr\00FCfsumme verwenden, ')
||unistr('um verlorene Updates zu ermitteln und die Version der Zeile zu bestimmen. Die Pr\00FCfsumme ist eine Hashfunktion aller Spaltenwerte f\00FCr die spezifische Tabellenzeile. Sie wird abgerufen, wenn der Datensatz aus der Datenbank abgefragt wird, und wird dann')
||unistr(' mit dem Hash des aktuellen Datensatzes als Bestandteil der <em>Automatischen Zeilenverarbeitung</em> verglichen. Wenn die beiden Werte identisch sind, wird mit dem Update fortgefahren, sonst l\00F6st die automatische Zeilenverarbeitung einen Fehler aus.')
||'</p>',
unistr('<p>Mit diesem Attribut k\00F6nnen Sie eine einzelne Spalte angeben, die die Zeilenversion enth\00E4lt, als Alternative zur Verwendung der integrierten Pr\00FCfsummenverarbeitung. Diese Spalte muss aktualisiert werden, wenn ein Datensatz in der Datenbank aktualis')
||'iert wird. Oracle empfiehlt, dass Sie einen "Vor Update"-Datenbanktrigger auf der Tabelle implementieren, um die Spalte mit der Zeilenversion zu inkrementieren oder anderweitig zu aktualisieren. Es wird davon ausgegangen, dass NUMBER-Spalten eine Fol'
||unistr('genummer f\00FCr die Zeile enthalten. DATE- und TIMESTAMP-Spalten k\00F6nnen ebenfalls verwendet werden. Der Vorteil der Verwendung einer einzelnen Spalte besteht darin, dass die &PRODUCT_NAME. Engine nicht die gesamte Zeile hashen muss, sondern stattdessen ')
||'einen einzelnen Spaltenwert vergleichen kann.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(361804814168854679.4414)
,p_plugin_id=>wwv_flow_imp.id(361799714569626543.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>8
,p_display_sequence=>80
,p_prompt=>'Laufzeit-WHERE-Klausel'
,p_attribute_type=>'TEXTAREA'
,p_is_required=>false
,p_is_common=>false
,p_max_length=>4000
,p_is_translatable=>false
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Begrenzen Sie die Abteilungen mit:',
'  <code>DEPTNO = 10</code>'))
,p_help_text=>unistr('Geben Sie die SQL-WHERE-Klausel ein, die an die generierte SELECT-Anweisung angeh\00E4ngt werden muss. Verwenden Sie dieses Attribut, um die Datens\00E4tze zu begrenzen, die innerhalb automatisch generierter SQL-Aufrufe verwendet werden.')
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(361802100261724338.4414)
,p_plugin_id=>wwv_flow_imp.id(361799714569626543.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>15
,p_display_sequence=>150
,p_prompt=>'Abrufmodus'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>false
,p_is_common=>false
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_deprecated_values=>'D'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Diese Option ist nur aus Gr\00FCnden der Abw\00E4rtskompatibilit\00E4t vorhanden.'),
'Bei neuen Anwendungen muss diese Einstellung immer leer bleiben.',
'Die Option "Speichercache bei Anzeige festlegen" ist veraltet und wird in Prozessen, die mit diesem Release von &PRODUCT_NAME. generiert wurden, nicht genutzt.',
'</p>',
'<p>',
unistr('Wenn ein Prozess f\00FCr den automatisierten Zeilenabruf eine Zeile ausw\00E4hlt, werden die entsprechenden Seitenelemente auf die abgerufenen Spaltenwerte gesetzt. Der Zeitpunkt wird von der Einstellung f\00FCr den DML-Abrufmodus bestimmt. Der Standardmodus akt')
||unistr('ualisiert den Sessionzustand im Speicher, sobald die Zeile abgerufen wird. Der Modus "Speichercache bei Anzeige festlegen" aktualisiert diesen Sessionzustand nur, wenn (und falls) das Element wiedergegeben wird. Wenn Sie den abgerufenen Wert f\00FCr das ')
||unistr('Element mit einer Syntax f\00FCr Bind-Variablen oder <code>v(''ITEM_NAME'')</code>-Syntax zwischen dem Zeitpunkt des Zeilenabrufs und dem Zeitpunkt der Elementwiedergabe referenzieren m\00FCssen, m\00FCssen Sie den Standardabrufmodus verwenden. Wenn Sie einen neue')
||unistr('n Prozess f\00FCr den automatischen Zeilenabruf erstellen, wird als Abrufmodus dieser Standardmodus festgelegt. Wenn Ihre Seitenlogik nicht vom Verhalten "Bei Anzeige" abh\00E4ngt, aktualisieren Sie nach M\00F6glichkeit diesen Prozess zur Verwendung des Standard')
||unistr('verhaltens. Sie erhalten dann die maximale Flexibilit\00E4t zum Referenzieren von abgerufenen Spaltenwerten w\00E4hrend der Seitenwiedergabe.'),
''))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(361803025912727611.4414)
,p_plugin_attribute_id=>wwv_flow_imp.id(361802100261724338.4414)
,p_display_sequence=>20
,p_display_value=>'Speichercache bei Anzeige festlegen [veraltet]'
,p_return_value=>'D'
);
end;
/
