,p_display_length=>40
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Geben Sie das Muster zum Erstellen der vollqualifizierten Distinguished Name-(DN-)Zeichenfolge f\00FCr DBMS_LDAP.SIMPLE_BIND_S ein, wenn Sie den exakten DN verwenden, oder die Suchbasis, wenn Sie nicht den exakten DN verwenden. Verwenden Sie <strong>%LDA')
||unistr('P_USER%</strong> als Platzhalter f\00FCr den Benutzernamen. Beispiel:'),
'<p>',
'<strong>Exakter DN</strong>',
'</p>',
'<p>',
'cn=%LDAP_USER%,l=amer,dc=yourdomain,dc=com',
'</p>',
'<p>',
'<strong>Nicht-exakter DN (Suchbasis)</strong>',
'</p>',
'<p>',
'dc=yourdomain,dc=com',
'</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(708104537708095412.4414)
,p_plugin_id=>wwv_flow_imp.id(707764939992010930.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>5
,p_display_sequence=>50
,p_prompt=>'Exakten Distinguished Name (DN) verwenden'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_default_value=>'Y'
,p_is_translatable=>false
,p_help_text=>unistr('Legen Sie fest, ob die Zeichenfolge f\00FCr den LDAP Distinguished Name (DN) exakt oder nicht exakt ist. Wenn sie nicht exakt ist, ist LDAP Distinguished Name (DN) die Suchbasis, und Sie m\00FCssen einen Suchfilter angeben.')
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(708207443165115942.4414)
,p_plugin_id=>wwv_flow_imp.id(707764939992010930.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>6
,p_display_sequence=>60
,p_prompt=>'Suchfilter'
