,p_display_length=>40
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(708104537708095412.4414)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie den Suchfilter ein, wenn Sie nicht den exakten Distinguished Name (DN) verwenden. Verwenden Sie <b>%LDAP_USER%</b> als Platzhalter f\00FCr den Benutzernamen. Beispiel:'),
'</p>',
'<p><pre>cn=%LDAP_USER%</pre></p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(708300825765129776.4414)
,p_plugin_id=>wwv_flow_imp.id(707764939992010930.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_prompt=>unistr('Bearbeitungsfunktion f\00FCr den LDAP-Benutzernamen')
,p_attribute_type=>'PLSQL FUNCTION BODY'
,p_is_required=>false
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Sie k\00F6nnen zus\00E4tzlichen Code angeben, der zur Umwandlung des Benutzernamens in ein Format ausgef\00FChrt werden soll, das dem LDAP-Verzeichniseintrag oder LDAP-Benutzernamen genau entspricht.'),
unistr('Die Bind-Variable :USERNAME enth\00E4lt den angegebenen Namen des Endbenutzers.'),
'Beispiel: Der folgende Code ruft eine Funktion auf, die alle "." durch "_" in der DN-Zeichenfolge ersetzt:</p>',
'',
'<p><pre>',
'return apex_custom_auth.ldap_dnprep(p_username => :USERNAME);',
'</pre></p>',
'',
unistr('<p>&PRODUCT_NAME. escapt den zur\00FCckgegebenen Benutzernamen basierend auf dem Authentifizierungsattribut <strong>Benutzernamen-Escaping</strong>.')))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(38288205752186126.4414)
,p_plugin_id=>wwv_flow_imp.id(707764939992010930.4414)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>8
,p_display_sequence=>80
,p_prompt=>'Benutzernamen-Escaping'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'STD'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Bevor Sie <strong>%LDAP_USER%</strong> im LDAP-Distinguished Name und in der Suchzeichenfolge ersetzen,',
'kann &PRODUCT_NAME. Sonderzeichen im Benutzernamen automatisch escapen.',
'<p/>',
unistr('Die m\00F6glichen Regeln f\00FCr das Escaping lauten wie folgt:'),
'<ul>',
'<li><strong>Standard</strong>:',
unistr('Sonderzeichen basierend auf RFC 4514 (f\00FCr Distinguished Names) und RFC 4515 (f\00FCr Suchzeichenfolgen) escapen.'),
unistr('Dar\00FCber hinaus werden Unicode-Zeichen escapt.'),
unistr('Dies ist die sicherste Einstellung. Diese kann aber zu Problemen mit einigen LDAP-Servern f\00FChren.</li>'),
'<li><strong>Nur Sonderzeichen</strong>:',
unistr('Sonderzeichen basierend auf RFC 4514 (f\00FCr Distinguished Names) und RFC 4515 (f\00FCr Suchzeichenfolgen) escapen.'),
'Keine Unicode-Zeichen escapen.</li>',
'<li><strong>Kein Escaping</strong>:',
'Keine Zeichen escapen.',
'Diese Einstellung kann unsicher sein,',
'wenn nicht eine <strong>Funktion zum Bearbeiten des Benutzernamens</strong> eingesetzt wurde, die',
'den Benutzernamen bereits escapt (z.B. mit apex_escape.ldap_dn oder apex_escape.ldap_search_filter).</li>',
'</ul>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(38288513717188434.4414)
,p_plugin_attribute_id=>wwv_flow_imp.id(38288205752186126.4414)
,p_display_sequence=>10
,p_display_value=>'Standard'
,p_return_value=>'STD'
);
wwv_flow_imp_shared.create_plugin_attr_value(
