,p_plugin_attribute_id=>wwv_flow_imp.id(38288205752186126.4414)
,p_display_sequence=>20
,p_display_value=>'Nur Sonderzeichen'
,p_return_value=>'ONLY'
);
wwv_flow_imp_shared.create_plugin_attr_value(
