,p_attribute_sequence=>7
,p_display_sequence=>45
,p_static_id=>'drag_and_drop'
,p_prompt=>'Drag-and-Drop'
,p_attribute_type=>'CHECKBOX'
,p_is_required=>false
,p_is_common=>false
