);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(731386319815053643.4414)
,p_plugin_attribute_id=>wwv_flow_imp.id(964835401087640042.4414)
,p_display_sequence=>20
,p_display_value=>'Tabelle APEX_APPLICATION_TEMP_FILES'
,p_return_value=>'APEX_APPLICATION_TEMP_FILES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Speichert die hochgeladenen Dateien in einem tempor\00E4ren Verzeichnis, auf das Sie mit der View APEX_APPLICATION_TEMP_FILES zugreifen k\00F6nnen. &PRODUCT_NAME. l\00F6scht die Dateien am Ende der Session oder am Ende der Uploadanforderung automatisch, je na')
||unistr('chdem, welche Option Sie f\00FCr <strong>Datei l\00F6schen bei</strong> ausw\00E4hlen.</p>'),
'<p>So greifen Sie auf eine Datei zu, wenn <strong>Mehrere Dateien zulassen</strong> auf <strong>Nein</strong> gesetzt ist:</p>',
'<pre>',
'select *',
'  from apex_application_temp_files',
' where name = :<em>page item name</em>;',
'</pre>',
'<p>So greifen Sie auf Dateien zu, wenn <strong>Mehrere Dateien zulassen</strong> auf <strong>Ja</strong> gesetzt ist:</p>',
'<pre>',
'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'begin',
'    l_file_names := apex_string.split (',
'                        p_str => :<em>page item name</em>,',
'                        p_sep => '':'' );',
'    for i in 1 .. l_file_names.count loop',
'        select *',
'          into l_file',
'          from apex_application_temp_files',
'         where name = l_file_names(i);',
'        -- add code here to store the uploaded file in your own table',
'    end loop;',
'end;',
'</pre>'))
);
