,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'  &lt;div class="cc-container"&gt;',
'    &lt;span class="cc-item"&gt;Name: &amp;NAME.&lt;/span&gt;',
'    {if ?CAPITAL/}&lt;span class="cc-item"&gt;Capital: &amp;CAPITAL.&lt;/span&gt;{endif/}',
