,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(2700405449462251.4414)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'JAVASCRIPT'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<dl><dt>Erh\00F6ht das Gehalt um 3 % f\00FCr Mitarbeiter, denen eine Gehaltserh\00F6hung zusteht:</dt>'),
'<dd><pre>',
'var rows;',
'function needsSalaryRaise( empno ) {',
unistr('  // Platzhalter f\00FCr komplizierte Logik zur Berechnung, ob dem Mitarbeiter eine Gehaltserh\00F6hung zusteht'),
'  return true;',
'}',
'rows = apex.conn.execute( "select empno from emp where deptno = :deptno", { deptno: apex.env.P2_DEPTNO } ).rows;',
'for ( var row of rows ) {',
'  if ( needsSalaryRaise( row.EMPNO )) {',
'    apex.conn.execute( "update emp set sal = sal * 1.03 where empno = :empno", { empno: row.EMPNO } );',
'  }',
'}',
'</pre></dd>',
'</dl>',
unistr('<p>In diesem Beispiel m\00FCssen Sie <code>P2_DEPTNO</code> in <strong>Weiterzuleitende Elemente</strong> eingeben.</p>')))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Geben Sie einen JavaScript-Block nur zur Ausf\00FChrung an, der auf dem Server ausgef\00FChrt wird.</p>'),
unistr('<p>Sie k\00F6nnen andere Seiten- oder Anwendungselemente in der Anwendung mit Bind-Syntax referenzieren (Beispiel: <code>apex.env.P1_MY_ITEM</code>). Alle referenzierten Elemente m\00FCssen auch in <strong>Weiterzuleitende Seitenelemente</strong> aufgenommen')
||' werden.</p>'))
);
